def mi_preset(kind, name):
    """Full settings for a preset (built in or the user's), or None."""
    kind = _mi_kind(kind)
    over = MI_PRESETS[kind].get(name)
    if over is None:
        over = mi_user_presets(kind).get(name)
    if over is None:
        return None
    s = dict(MI_DEFAULTS[kind])
    s.update(over)
    return s
# =============================================================================
# Moss and Ivy - scatter groups
# =============================================================================
# The user, 2026-11-03: "a 'build a scatter group' ... it showed a bounding box like the roof does ... in that
# group there's like a list of stuff in it, you can add / remove / undo and click things to control them". One
# scatteredObjects####_GRP holds what it scatters onto (meshes and whole groups, read fresh at every regrow),
# a wireframe box round it to click (scatteredObjects####_CTL, beside the group, linked both ways by uuid: the user
# drags groups into a publish group without it) and layers: each its own type (Moss, Grass,
# Leaves, Leaf piles, Moss tufts, Ivy), settings, area (picked faces / points), seed, on or off. Two layers of
# a type each get their own parts (mossGreen_C_..., mossGreen2_C_...). A part mesh exists only while it holds
# something (the user: empty parts showing as planes at the origin); one that empties while you edit hides
# (keeping its material) and Bake removes it. Structure (layers, surfaces, areas, toggles) is undoable JSON;
# geometry is built through the API outside the undo queue and rebuilt whenever the JSON and what was built
# differ (after an undo / redo).
# Drawing (the user: "click draw on any surface and then draw a curve / line over surfaces (undoable as you
# go), then hit 'scatter on drawing' ... control falloff"): a layer may hold strokes (points local to the mesh
# each was drawn on, so they follow it); the layer then goes Width round them, fading over Falloff, and only
# the faces within reach are analysed (_MiDrawing).

SC_ATTR = "unlokScatter"           # string on the group: JSON (surfaces, udim, layers)
SC_BAKED = "unlokScatterBaked"     # the same after Bake
SC_STAMP = "unlokScatterStamp"     # string on the group: a token set after each build (a redo resets it)
SC_GROWN = "unlokScatterGrown"     # string on the group: the JSON its parts were last grown from
SC_COUNTS = "unlokScatterCounts"   # string on the group: each layer's counts at that build
SC_SURF = "unlokScatterSurfaces"   # string on the group: its surfaces' mesh keys at that build
SC_PART = "unlokScatterPart"       # string on a part's shape: "<layer id>/<part>"
SC_SHOOTS = "unlokScatterShoots"   # string on a Moss layer's instanced shoots transform: "<layer id>/shoots"
SC_SHOOT_SHAPE = "unlokShootShape"  # int on each instanced shoot shape: its instancer index
SC_BOX_ATTR = "unlokScatterBox"    # bool on the box
SC_BOX_OF = "unlokScatterBoxOf"    # string on the box: its group's uuid
SC_BOX_ID = "unlokScatterBoxId"    # string on the group: its box's uuid
SC_BOX_AUTO = "unlokScatterBoxAuto"  # bool on a box made outside the undo queue (a Ctrl+D copy's)
SC_BLOCKER_ATTR = "unlokScatterBlocker"  # string on a blocker box the tool made: its group's uuid
SC_BLOCK_GAP = 0.1  # metres: just outside a blocker things thin out (none inside)
# the control group (the user, 2026-11-09: only normal geometry in what gets published; the box, instancers,
# particles and hidden shapes in a group of their own, next to the box): scatterControl####_GRP
SC_CTL = "unlokScatterControl"     # string on a control group: its scatter group's uuid
SC_CTL_ID = "unlokScatterControlId"  # string on the scatter group: its control group's uuid
SC_CTL_AUTO = "unlokScatterControlAuto"  # bool on a control group made for a Ctrl+D copy (outside the undo queue)
SC_CTL_STEM = "scatterControl"
SC_STEM = "scatteredObjects"
SC_VERSION = 1
SC_PLACE = ("coverage", "spread", "slope", "crevices", "creases", "edges", "patchiness", "patch_size", "mess")
SC_DEBRIS_COMMON = SC_PLACE + ("size_var", "detail", "seed", "stacks", "stack_layout") + tuple(MI_FADE_DEFAULTS)
SC_TYPES = collections.OrderedDict([
    ("Moss", {"parts": (("moss", "mossGreen"), ("strands", "mossStrand"), ("capsules", "mossSpore")),
              "keys": tuple(k for k in MOSS_DEFAULTS if k != "udim"), "over": {"shoots": "Instances"},
              "new": MOSS_NEW_LOOK}),
    ("Grass", {"parts": (("grass", "grassDry"),),
               "keys": SC_DEBRIS_COMMON + ("grass", "bunch_size", "grass_length", "fullness", "comb", "droop",
                                           "blade_width", "grass_pile", "grass_strays", "bunch_var",
                                           "bunch_shape", "blade_scatter", "bunch_blades", "on_layers"),
               "over": {"slope": 40.0, "grass": 1.5}, "new": {"grass_pile": 0.6, "on_layers": True}}),
    ("Leaves", {"parts": (("litter", "leafDry"),),
                "keys": SC_DEBRIS_COMMON + ("leaves", "leaf_size", "curl", "drape", "bend_size", "on_moss",
                                             "on_layers"),
                "over": {"slope": 35.0, "leaves": 8.0}, "new": {"on_moss": True, "on_layers": True}}),
    ("Leaf piles", {"parts": (("piles", "leafPile"),),
                    "keys": SC_DEBRIS_COMMON + ("piles", "pile_size", "leaf_size", "curl", "drape", "on_moss",
                                                "on_layers"),
                    "over": {"slope": 30.0, "piles": 0.6, "creases": 1.0}, "new": {"on_moss": True,
                                                                                   "on_layers": True}}),
    ("Jungle leaves", {"parts": (("green", "leafJungle"), ("dry", "leafJungleDry")),
                       "keys": SC_DEBRIS_COMMON + ("jungle", "jungle_size", "jungle_cluster", "jungle_shape",
                                                   "jungle_green", "jungle_tear", "curl", "drape", "bend_size",
                                                   "on_moss", "on_layers"),
                       "over": {"slope": 35.0, "jungle": 0.6, "creases": 0.8}, "new": {"on_moss": True,
                                                                                       "on_layers": True}}),
    ("Moss tufts", {"parts": (("tufts", "mossTuft"),), "keys": SC_DEBRIS_COMMON + ("tufts", "tuft_size"),
                    "over": {"slope": 60.0, "tufts": 6.0}}),
    ("Specks", {"parts": (("specks", "mossSpeck"), ("dirt", "dirtSpeck")),
                "keys": SC_DEBRIS_COMMON + ("specks", "speck_size", "speck_dirt", "speck_cluster", "speck_spread"),
                "over": {"slope": 90.0, "specks": 40.0, "coverage": 0.8, "crevices": 0.3, "edges": 0.0,
                         "patchiness": 0.5, "creases": 0.5}}),
    ("Ivy", {"parts": (("stems", "ivyStem"), ("leaves", "ivyLeaf")),
             "keys": tuple(k for k in IVY_DEFAULTS if k != "udim"), "over": {}})])
SC_DEBRIS_ITEMS = {"Grass": "grass", "Leaves": "leaves", "Leaf piles": "piles", "Moss tufts": "tufts",
                   "Jungle leaves": "jungle", "Specks": "specks"}
SC_DEBRIS_OUT = {"Grass": (("grass", "grass"),), "Leaves": (("litter", "litter"),),
                 "Leaf piles": (("litter", "piles"),), "Moss tufts": (("tufts", "tufts"),),
                 "Jungle leaves": (("jungle", "green"), ("jungle_dry", "dry")),
                 "Specks": (("specks", "specks"), ("dirt", "dirt"))}  # debris_build's mesh -> part
SC_DRAW_DEFAULTS = {"draw_width": 0.3, "draw_falloff": 0.5, "draw_follow": 0.5}  # metres, fractions
SC_DRAW_MAX_POINTS = 6000  # stored per layer (thinned evenly past it)
SC_DRAW_ON = ("Surfaces", "Selected", "Everything")  # what Draw on Surfaces draws on
_SC_BUILT = collections.OrderedDict()  # (group, layer id, layer JSON, surfaces) -> the layer's parts, counts
_SC_LAST = {}   # group -> (JSON, stamp) it was last built from
_SC_SURF = {}   # group -> its surfaces' mesh keys at that build (JSON-like lists)
_SC_WROTE = {}  # (group, layer id / part) -> what was last written (mesh identity, tiles)
# Pause (the user: "hit pause, make a bunch of edits, then hit play, and it
# would all live update"): while on, edits are saved to the groups' JSON and
# nothing grows. base: group -> the JSON Ctrl+Z goes back to (its last
# undoable state); seen: group -> the JSON this tool last wrote; force:
# groups Regrow was pressed for.
_SC_HOLD = {"on": False, "base": {}, "seen": {}, "force": set()}
# Draft (the user: "scattering moss is slowwwwwww, it takes ages to update"):
# while on, a moss layer that grows (a live edit, a new layer, an undo) grows
# a coarse bed with nothing standing out of it, noted "draft" in its counts
# (saved on the group, so a draft stays marked when the scene opens again);
# Full detail grows the drafts properly. later: groups Full detail was
# pressed for while paused (grown at Play).
_SC_DRAFT = {"on": False, "later": set()}


def sc_type(name):
    return name if name in SC_TYPES else "Moss"


def sc_defaults(typ):
    """A layer type's settings (its keys only)."""
    typ = sc_type(typ)
    base = MOSS_DEFAULTS if typ == "Moss" else (IVY_DEFAULTS if typ == "Ivy" else DEBRIS_DEFAULTS)
    out = {k: base[k] for k in SC_TYPES[typ]["keys"]}
    out.update(SC_TYPES[typ]["over"])
    out.update(SC_DRAW_DEFAULTS)
    return out


def sc_start_settings(typ):
    """What a new layer of a type starts with: its defaults and its new look."""
    s = sc_defaults(typ)
    s.update(SC_TYPES[sc_type(typ)].get("new", {}))
    return s


def sc_settings(layer):
    """A layer's settings: its type's defaults under what it stores."""
    s = sc_defaults(layer.get("type"))
    s.update({k: v for k, v in (layer.get("s") or {}).items() if k in s})
    return s


def _sc_new_layer(data, typ, settings=None, name=None):
    """A layer dict for a group's data (not added): unique id and tag (the
    number its parts carry after the material: "" for the first of a type,
    then 2, 3...)."""
    typ = sc_type(typ)
    n = int(data.get("next", 1))
    data["next"] = n + 1
    used = set(l.get("tag", "") for l in data.get("layers", []) if l.get("type") == typ)
    tag, k = "", 1
    while tag in used:
        k += 1
        tag = str(k)
    s = sc_start_settings(typ)  # a new layer's look (older layers lack these keys: they keep theirs)
    s.update({k2: v for k2, v in (settings or {}).items() if k2 in s})
    return {"id": "L%d" % n, "type": typ, "tag": tag, "on": True, "s": s,
            "name": name or (typ + (" " + tag if tag else "")), "seeds": [], "faces": {}, "draw": {}}


def sc_store_drawing(strokes):
    """Strokes [[(world point, mesh it was drawn on), ...], ...] as a layer's
    "draw": {"t": [mesh uuids], "k": [[[mesh index, local x, y, z], ...]]}
    (local to the mesh, so the drawing follows it; points on no mesh, or a
    deleted one, are dropped; thinned evenly past SC_DRAW_MAX_POINTS)."""
    total = sum(len(st) for st in strokes or ())
    every = max(1, int(math.ceil(total / float(SC_DRAW_MAX_POINTS))))
    uids, index, mats, out = [], {}, {}, []
    for st in strokes or ():
        pts = [q for q in st if q[1]]
        if every > 1:
            pts = pts[::every] + ([pts[-1]] if pts and (len(pts) - 1) % every else [])
        row = []
        for p, mesh in pts:
            node = mesh
            if cmds.objExists(node) and cmds.objectType(node, isAType="shape"):
                node = cmds.listRelatives(node, parent=True, fullPath=True)[0]
            if node not in mats:
                dag = get_dag_path(node) if cmds.objExists(node) else None
                mats[node] = dag.inclusiveMatrixInverse() if dag is not None else None
                if dag is not None:
                    index[node] = len(uids)
                    uids.append(cmds.ls(node, uuid=True)[0])
            if mats[node] is None:
                continue
            lp = om.MPoint(p[0], p[1], p[2]) * mats[node]
            row.append([index[node], round(lp.x, 5), round(lp.y, 5), round(lp.z, 5)])
        if row:
            out.append(row)
    return {"t": uids, "k": out} if out else {}


def sc_drawing(layer):
    """A layer's strokes in world space now ([[point, ...], ...])."""
    return [st for st in _sc_drawing_rows(layer) if st]


def _sc_drawing_rows(layer):
    """Every stored stroke of a layer in world space now, in order (a stroke
    whose meshes are all gone: [])."""
    draw = (layer or {}).get("draw") or {}
    mats = []
    for uid in draw.get("t") or []:
        found = cmds.ls(uid, long=True) or []
        mats.append(get_dag_path(found[0]).inclusiveMatrix() if found else None)
    out = []
    for row in draw.get("k") or []:
        st = []
        for ti, x, y, z in row:
            if 0 <= ti < len(mats) and mats[ti] is not None:
                w = om.MPoint(x, y, z) * mats[ti]
                st.append((w.x, w.y, w.z))
        out.append(st)
    return out


def sc_stroke_info(layer):
    """[(points, [short names of the meshes it's on])] per stored stroke."""
    draw = (layer or {}).get("draw") or {}
    names = []
    for uid in draw.get("t") or []:
        found = cmds.ls(uid, long=True) or []
        names.append(short_name(found[0]) if found else None)
    out = []
    for row in draw.get("k") or []:
        on = []
        for q in row:
            n = names[q[0]] if 0 <= q[0] < len(names) else None
            if n and n not in on:
                on.append(n)
        out.append((len(row), on))
    return out


def _sc_draw_keep(draw, keep):
    """A stored drawing with only the strokes keep (indices) in it."""
    rows, uids = draw.get("k") or [], draw.get("t") or []
    index, out_t, out_k = {}, [], []
    for i in keep:
        if not 0 <= i < len(rows):
            continue
        row = []
        for ti, x, y, z in rows[i]:
            if not 0 <= ti < len(uids):
                continue
            if ti not in index:
                index[ti] = len(out_t)
                out_t.append(uids[ti])
            row.append([index[ti], x, y, z])
        if row:
            out_k.append(row)
    return {"t": out_t, "k": out_k} if out_k else {}


def _sc_draw_join(a, b):
    """Two stored drawings as one (b's strokes after a's), thinned evenly
    past SC_DRAW_MAX_POINTS."""
    uids = list(a.get("t") or [])
    index = dict((u, i) for i, u in enumerate(uids))
    rows = [list(r) for r in a.get("k") or []]
    bt = b.get("t") or []
    for row in b.get("k") or []:
        new = []
        for ti, x, y, z in row:
            if not 0 <= ti < len(bt):
                continue
            if bt[ti] not in index:
                index[bt[ti]] = len(uids)
                uids.append(bt[ti])
            new.append([index[bt[ti]], x, y, z])
        if new:
            rows.append(new)
    every = max(1, int(math.ceil(sum(len(r) for r in rows) / float(SC_DRAW_MAX_POINTS))))
    if every > 1:
        rows = [r[::every] + ([r[-1]] if (len(r) - 1) % every else []) for r in rows]
    return _sc_draw_keep({"t": uids, "k": rows}, range(len(rows))) if rows else {}


def sc_draw_targets(nodes):
    """The visible mesh shapes of nodes (meshes, or groups: every mesh under
    them): what Draw on Selected draws on."""
    out = []
    for node in nodes or ():
        if not cmds.objExists(node):
            continue
        if cmds.objectType(node, isAType="mesh"):
            shapes = [long_name(node)]
        else:
            shapes = cmds.listRelatives(node, allDescendents=True, type="mesh", fullPath=True,
                                        noIntermediate=True) or []
        for sh in cmds.ls(shapes, visible=True, long=True) or []:
            if sh not in out:
                out.append(sh)
    return out


_SC_PART_NAME = re.compile(r"_C_%s\d{4}_GEP$" % SC_STEM)


def _sc_scatter_mesh(dag):
    """A scatter part's mesh, live or baked, wherever it's been moved to
    (Bake keeps its unlokScatterPart tag; an older one by its name), or a
    group's box."""
    try:
        fn0 = om.MFnDependencyNode(dag.node())
        if fn0.hasAttribute(SC_PART) or fn0.hasAttribute(SC_SHOOT_SHAPE):
            return True
        parent = om.MDagPath(dag)
        parent.pop()
        fn = om.MFnDependencyNode(parent.node())
        return fn.hasAttribute(SC_BOX_ATTR) or bool(_SC_PART_NAME.search(fn.name()))
    except RuntimeError:
        return False


def _sc_box_mesh(dag):
    """A scatter group's box (its shape's dag)."""
    try:
        parent = om.MDagPath(dag)
        parent.pop()
        return om.MFnDependencyNode(parent.node()).hasAttribute(SC_BOX_ATTR)
    except RuntimeError:
        return False


def sc_drawing_meshes(strokes):
    """The meshes (transforms) a drawing's strokes were drawn on."""
    out = []
    for st in strokes or ():
        for _, mesh in st:
            if mesh and cmds.objExists(mesh):
                node = cmds.listRelatives(mesh, parent=True, fullPath=True)[0] if \
                    cmds.objectType(mesh, isAType="shape") else long_name(mesh)
                if node not in out:
                    out.append(node)
    return out


# ------------------------------------------------------- influence paint
# The user, 2026-11-05: "more control, like a brush to influence paint, to add / remove influence (would be great
# if this had subtle ability, like not 100% opacity, but like 10% masking mode to do lots of strokes to subtly
# influence parts)". A layer's "paint" is an influence from -1 (nothing grows) through 0 (as it grows by itself)
# to +1 (full), on a sparse grid of SC_PAINT_CELL cells local to each mesh (it follows the mesh; guide meshes are
# often a few big faces, so it can't live on their vertices). Only cells a stroke changed are kept; the rest of
# the surface has the base (Flood). Stored as {"t": [mesh uuids], "b": base, "m": [[cell size in the mesh's own
# units, [i, j, k, value, ...]], ...]}, values in 1 / SC_PAINT_Q steps (so a 10% stroke's soft edge still counts).
SC_PAINT_CELL = 0.1      # metres: one paint cell
SC_PAINT_Q = 1000        # stored steps per 1
SC_PAINT_MODES = ("Add", "Remove", "Smooth")
SC_PAINT_DEFAULTS = {"mode": "Add", "radius": 0.3, "opacity": 0.1}  # radius in metres
SC_PAINT_TRI_CELL = 0.5  # metres: the grid a dab finds its triangles in
_SC_PAINT_TRIS = collections.OrderedDict()  # mesh state -> (cell, {cell: triangle ids}, big ids, triangles)


def _sc_paint_xform(m16, p):
    """A point times a 4x4 matrix given as 16 floats (row vectors, like MPoint * MMatrix)."""
    x, y, z = p
    return (x * m16[0] + y * m16[4] + z * m16[8] + m16[12], x * m16[1] + y * m16[5] + z * m16[9] + m16[13],
            x * m16[2] + y * m16[6] + z * m16[10] + m16[14])


def _sc_paint_falloff(t):
    """The brush: 1 at its centre easing to 0 at its rim (t = distance / radius)."""
    if t >= 1.0:
        return 0.0
    u = 1.0 - t * t
    return u * u


def _sc_paint_space(node):
    """(uuid, world matrix, inverse, scale) of a mesh's transform as 16 floats, or None."""
    if not node or not cmds.objExists(node):
        return None
    if cmds.objectType(node, isAType="shape"):
        node = cmds.listRelatives(node, parent=True, fullPath=True)[0]
    dag = get_dag_path(node)
    if dag is None:
        return None
    mat = dag.inclusiveMatrix()
    m16 = list(mat)
    scale = (sum(math.sqrt(m16[4 * r] ** 2 + m16[4 * r + 1] ** 2 + m16[4 * r + 2] ** 2) for r in range(3)) / 3.0)
    return cmds.ls(node, uuid=True)[0], m16, list(mat.inverse()), max(scale, 1e-9)


def _sc_paint_tris(node):
    """A mesh's world triangles in a grid (cached while the mesh is unchanged)."""
    key = _mi_mesh_key(node)
    hit = _mi_cache_get(_SC_PAINT_TRIS, key)
    if hit is not None:
        return hit
    tris = _mi_triangles(node)[1]
    cell = SC_PAINT_TRI_CELL / scene_m_per_unit()
    grid, big = {}, []
    for ti, (a, b, c, n, f) in enumerate(tris):
        lo = [int(math.floor(min(a[k], b[k], c[k]) / cell)) for k in range(3)]
        hi = [int(math.floor(max(a[k], b[k], c[k]) / cell)) for k in range(3)]
        if (hi[0] - lo[0] + 1) * (hi[1] - lo[1] + 1) * (hi[2] - lo[2] + 1) > 512:
            big.append(ti)
            continue
        for i in range(lo[0], hi[0] + 1):
            for j in range(lo[1], hi[1] + 1):
                for k in range(lo[2], hi[2] + 1):
                    grid.setdefault((i, j, k), []).append(ti)
    hit = (cell, grid, big, tris)
    _SC_PAINT_TRIS[key] = hit
    _mi_trim(_SC_PAINT_TRIS)
    return hit


def _sc_paint_cells(node, p, r, hl, inv):
    """The cells (keys in the mesh's local grid of size hl) that its surface
    passes through within r of world point p: each triangle near p is
    sampled at half a cell where it cuts the sphere."""
    cell, grid, big, tris = _sc_paint_tris(node)
    lo = [int(math.floor((p[k] - r) / cell)) for k in range(3)]
    hi = [int(math.floor((p[k] + r) / cell)) for k in range(3)]
    ids = set(big)
    for i in range(lo[0], hi[0] + 1):
        for j in range(lo[1], hi[1] + 1):
            for k in range(lo[2], hi[2] + 1):
                ids.update(grid.get((i, j, k), ()))
    scale = math.sqrt(inv[0] ** 2 + inv[1] ** 2 + inv[2] ** 2) or 1.0  # world -> local length
    step = 0.5 * hl / scale  # world spacing of the samples: half a cell
    r2 = r * r
    keys = set()
    fl = math.floor
    for ti in ids:
        a, b, c, n, _ = tris[ti]
        pa = _rl_sub(p, a)
        d = _rl_dot(pa, n)
        if d * d >= r2:
            continue
        for q in (a, b, c, ((a[0] + b[0] + c[0]) / 3.0, (a[1] + b[1] + c[1]) / 3.0, (a[2] + b[2] + c[2]) / 3.0)):
            e = _rl_sub(q, p)
            if _rl_dot(e, e) <= r2:  # small triangles: their corners and middle
                lq = _sc_paint_xform(inv, q)
                keys.add((int(fl(lq[0] / hl)), int(fl(lq[1] / hl)), int(fl(lq[2] / hl))))
        e1 = _rl_sub(b, a)
        L1 = _rl_len(e1)
        if L1 < 1e-12:
            continue
        u = _rl_mul(e1, 1.0 / L1)
        v = _rl_cross(n, u)
        ca = _rl_sub(c, a)
        cx, cy = _rl_dot(ca, u), _rl_dot(ca, v)
        if abs(cy) < 1e-12:
            continue
        rho2 = r2 - d * d
        rho = math.sqrt(rho2)
        qx, qy = _rl_dot(pa, u), _rl_dot(pa, v)  # the sphere's circle on the triangle's plane
        x0, x1 = max(min(0.0, cx), qx - rho), min(max(L1, cx), qx + rho)
        y0, y1 = max(min(0.0, cy), qy - rho), min(max(0.0, cy), qy + rho)
        if x0 > x1 or y0 > y1:
            continue
        la = _sc_paint_xform(inv, a)
        lu = (u[0] * inv[0] + u[1] * inv[4] + u[2] * inv[8], u[0] * inv[1] + u[1] * inv[5] + u[2] * inv[9],
              u[0] * inv[2] + u[1] * inv[6] + u[2] * inv[10])
        lv = (v[0] * inv[0] + v[1] * inv[4] + v[2] * inv[8], v[0] * inv[1] + v[1] * inv[5] + v[2] * inv[9],
              v[0] * inv[2] + v[1] * inv[6] + v[2] * inv[10])
        tol = 1e-6
        for iy in range(int(math.ceil(y0 / step)), int(fl(y1 / step)) + 1):
            y = iy * step
            t = y / cy
            if t < -tol or t > 1.0 + tol:
                continue
            dy2 = (y - qy) * (y - qy)
            for ix in range(int(math.ceil(x0 / step)), int(fl(x1 / step)) + 1):
                x = ix * step
                if (x - qx) * (x - qx) + dy2 > rho2:
                    continue
                s = (x - t * cx) / L1
                if s < -tol or s + t > 1.0 + tol:
                    continue
                keys.add((int(fl((la[0] + lu[0] * x + lv[0] * y) / hl)), int(fl((la[1] + lu[1] * x + lv[1] * y) / hl)),
                          int(fl((la[2] + lu[2] * x + lv[2] * y) / hl))))
    return keys


_SC_NEAR = tuple((i, j, k) for i in (-1, 0, 1) for j in (-1, 0, 1) for k in (-1, 0, 1))


class ScPaint(object):
    """A layer's influence paint to edit: base (-1..1) and, per mesh uuid,
    [cell size in its own units, {(i, j, k): value}]. dab / flood / clear
    change it; dump() is what the layer stores ({} when nothing's painted)."""

    def __init__(self, paint=None):
        paint = paint or {}
        q = float(SC_PAINT_Q)
        self.base = clamp(paint.get("b", 0) / q, -1.0, 1.0)
        self.meshes = collections.OrderedDict()
        for uid, entry in zip(paint.get("t") or [], paint.get("m") or []):
            flat = entry[1]
            self.meshes[uid] = [float(entry[0]), dict(((flat[k], flat[k + 1], flat[k + 2]),
                                                       clamp(flat[k + 3] / q, -1.0, 1.0))
                                                      for k in range(0, len(flat) - 3, 4))]
        self._start = None

    def begin_stroke(self):
        """From here until end_stroke, Add / Remove dabs are one stroke: a
        cell moves at most opacity (x the falloff) from where the stroke
        found it, however many dabs overlap it - so ten 10% strokes, not
        one, paint a place in."""
        self._start = {}

    def end_stroke(self):
        self._start = None

    def dump(self):
        q = SC_PAINT_Q
        b = int(round(self.base * q))
        uids, ms = [], []
        for uid, (hl, cells) in self.meshes.items():
            flat = []
            for key in sorted(cells):
                v = int(round(cells[key] * q))
                if v != b:
                    flat.extend((key[0], key[1], key[2], v))
            if flat:
                uids.append(uid)
                ms.append([round(hl, 7), flat])
        if not ms and not b:
            return {}
        return {"t": uids, "b": b, "m": ms}

    def count(self):
        """Cells painted (different from the base)."""
        return sum(1 for hl, cells in self.meshes.values() for v in cells.values() if abs(v - self.base) >= 0.0005)

    def dab(self, p, radius, opacity, mode, nodes):
        """One dab of the brush at world point p (radius in scene units) on
        the meshes (transforms) given: Add / Remove move the cells under it
        towards +1 / -1 by opacity x the falloff, Smooth towards the average
        round them. Returns how many cells changed."""
        r = max(float(radius), 1e-6)
        o = clamp(float(opacity), 0.0, 1.0)
        h = SC_PAINT_CELL / scene_m_per_unit()
        smooth = mode == SC_PAINT_MODES[2]
        sign = -1.0 if mode == SC_PAINT_MODES[1] else 1.0
        changed = 0
        for node in nodes:
            info = _sc_paint_space(node)
            if info is None:
                continue
            uid, m16, inv, scale = info
            entry = self.meshes.get(uid)
            hl = entry[0] if entry else h / scale
            keys = _sc_paint_cells(node, p, r, hl, inv)
            if not keys:
                continue
            if entry is None:
                entry = self.meshes[uid] = [hl, {}]
            cells = entry[1]
            before = dict(cells) if smooth else cells
            base = self.base
            for key in keys:
                w = _sc_paint_xform(m16, ((key[0] + 0.5) * hl, (key[1] + 0.5) * hl, (key[2] + 0.5) * hl))
                f = o * _sc_paint_falloff(_rl_len(_rl_sub(w, p)) / r)
                if f <= 1e-5:
                    continue
                v = before.get(key, base)
                if smooth:
                    tot = n = 0.0
                    for dx, dy, dz in _SC_NEAR:
                        nk = (key[0] + dx, key[1] + dy, key[2] + dz)
                        nv = before.get(nk)
                        if nv is None and nk in keys:  # on the surface, not painted yet: the base
                            nv = base
                        if nv is not None:
                            tot += nv
                            n += 1.0
                    new = v + f * (tot / n - v)
                elif self._start is not None:  # in a stroke: up to opacity past where it started
                    v0 = self._start.setdefault((uid, key), v)
                    new = clamp(v0 + sign * f, -1.0, 1.0)
                    new = max(v, new) if sign > 0 else min(v, new)
                else:
                    new = clamp(v + sign * f, -1.0, 1.0)
                if abs(new - v) > 1e-7:
                    cells[key] = new
                    changed += 1
        return changed

    def flood(self, opacity, mode):
        """Every cell and the base (the whole surface) at once: Add / Remove
        by opacity, Smooth blurs what's painted."""
        o = clamp(float(opacity), 0.0, 1.0)
        if mode == SC_PAINT_MODES[2]:
            for hl, cells in self.meshes.values():
                before = dict(cells)
                for key, v in before.items():
                    tot = n = 0.0
                    for dx, dy, dz in _SC_NEAR:
                        nv = before.get((key[0] + dx, key[1] + dy, key[2] + dz))
                        if nv is not None:
                            tot += nv
                            n += 1.0
                    cells[key] = v + o * (tot / n - v)
            return
        d = -o if mode == SC_PAINT_MODES[1] else o
        self.base = clamp(self.base + d, -1.0, 1.0)
        for hl, cells in self.meshes.values():
            for key in cells:
                cells[key] = clamp(cells[key] + d, -1.0, 1.0)

    def clear(self):
        self.base = 0.0
        self.meshes.clear()


class _MiPaint(object):
    """A layer's influence paint at build time: at(p) = -1..1 at a world
    point (the painted cells within 1.5 cells, nearer ones counting more;
    the base where there are none). top: the most anywhere (a layer at
    Coverage 0 still grows where it's painted in). Its repr goes in the
    build caches' keys."""

    W0 = 0.005  # how much the base counts against the cells round a point

    def __init__(self, paint):
        sp = paint if isinstance(paint, ScPaint) else ScPaint(paint)
        self.base = sp.base
        self.top = sp.base
        self.R = 1.5 * SC_PAINT_CELL / scene_m_per_unit()
        self.grid = {}
        c = self.R
        lo, hi = [1e30] * 3, [-1e30] * 3
        mats = []
        for uid, (hl, cells) in sp.meshes.items():
            found = cmds.ls(uid, long=True) or []
            dag = get_dag_path(found[0]) if found else None
            if dag is None or not cells:
                continue
            m16 = list(dag.inclusiveMatrix())
            mats.append((uid, tuple(round(v, 6) for v in m16)))
            for (i, j, k), v in cells.items():
                w = _sc_paint_xform(m16, ((i + 0.5) * hl, (j + 0.5) * hl, (k + 0.5) * hl))
                self.grid.setdefault((int(math.floor(w[0] / c)), int(math.floor(w[1] / c)),
                                      int(math.floor(w[2] / c))), []).append((w[0], w[1], w[2], v))
                for a in range(3):
                    lo[a], hi[a] = min(lo[a], w[a]), max(hi[a], w[a])
                if v > self.top:
                    self.top = v
        self.lo = [x - c for x in lo]
        self.hi = [x + c for x in hi]
        self.key = hash((json.dumps(sp.dump(), sort_keys=True), tuple(mats)))

    def __repr__(self):
        return "<influence paint %x>" % (self.key & 0xffffffffffff)

    def at(self, p):
        x, y, z = p
        lo, hi = self.lo, self.hi
        if not self.grid or x < lo[0] or y < lo[1] or z < lo[2] or x > hi[0] or y > hi[1] or z > hi[2]:
            return self.base
        c, R2 = self.R, self.R * self.R
        fx, fy, fz = x / c, y / c, z / c
        ix, iy, iz = int(math.floor(fx)), int(math.floor(fy)), int(math.floor(fz))
        xs = (ix, ix - 1 if fx - ix < 0.5 else ix + 1)
        ys = (iy, iy - 1 if fy - iy < 0.5 else iy + 1)
        zs = (iz, iz - 1 if fz - iz < 0.5 else iz + 1)
        sw = self.W0
        sv = self.W0 * self.base
        grid = self.grid
        for i in xs:
            for j in ys:
                for k in zs:
                    for qx, qy, qz, v in grid.get((i, j, k), ()):
                        d2 = (qx - x) * (qx - x) + (qy - y) * (qy - y) + (qz - z) * (qz - z)
                        if d2 < R2:
                            w = 1.0 - d2 / R2
                            w *= w
                            sw += w
                            sv += w * v
        return clamp(sv / sw, -1.0, 1.0)


class _MiInfluence(object):
    """Ivy: its Height fade (or none) and the layer's paint together, at(p) 0..1."""

    def __init__(self, fade, paint):
        self.fade, self.paint = fade, paint

    def at(self, p):
        f = 1.0 if self.fade is None else self.fade.at(p)
        k = self.paint.at(p)
        return f + k * (1.0 - f) if k > 0.0 else f * (1.0 + k)


class _ScBlocked(object):
    """A layer's influence paint (_MiPaint or None) with the group's
    blockers (the user, 2026-11-12: "a quick blockers system for scatters,
    same as the thatched roofs ... block things from spawning in certain
    areas"): at(p) is -1 (nothing grows) inside any blocker box, easing
    back to the paint over SC_BLOCK_GAP outside it; blocked(p): inside one
    (debris checks each item's own spot too). boxes: world boxes {"c", "u",
    "h"} (_th_blocker_box)."""

    def __init__(self, paint, boxes):
        self.paint = paint
        self.base = paint.base if paint is not None else 0.0
        self.top = paint.top if paint is not None else 0.0
        self.gap = SC_BLOCK_GAP / scene_m_per_unit()
        self.boxes = []
        for b in boxes:
            c, u, h = tuple(b["c"]), [tuple(v) for v in b["u"]], tuple(b["h"])
            r = [sum(abs(u[k][i]) * h[k] for k in range(3)) + self.gap for i in range(3)]  # its world reach
            self.boxes.append((c, u, h, [c[i] - r[i] for i in range(3)], [c[i] + r[i] for i in range(3)]))
        self.key = hash((paint.key if paint is not None else 0,
                         json.dumps([[b["c"], b["u"], b["h"]] for b in boxes], sort_keys=True)))

    def __repr__(self):
        return "<blocked paint %x>" % (self.key & 0xffffffffffff)

    def _out(self, p):
        """How far p is outside the nearest blocker (0 inside), or None past every gap."""
        best = None
        for c, u, h, lo, hi in self.boxes:
            if p[0] < lo[0] or p[1] < lo[1] or p[2] < lo[2] or p[0] > hi[0] or p[1] > hi[1] or p[2] > hi[2]:
                continue
            d = (p[0] - c[0], p[1] - c[1], p[2] - c[2])
            e2 = 0.0
            for k in range(3):
                e = abs(d[0] * u[k][0] + d[1] * u[k][1] + d[2] * u[k][2]) - h[k]
                if e > 0.0:
                    e2 += e * e
            if best is None or e2 < best:
                best = e2
                if not e2:
                    return 0.0
        return None if best is None else math.sqrt(best)

    def blocked(self, p):
        return self._out(p) == 0.0

    def at(self, p):
        k = self.paint.at(p) if self.paint is not None else 0.0
        d = self._out(p)
        if d is None or d >= self.gap:
            return k
        if d <= 0.0:
            return -1.0
        return min(k, -(1.0 - d / self.gap) ** 2)


def _sc_paint_margin(margin, k, cov):
    """A spot's coverage margin with influence k painted on it (cov: the
    layer's Coverage): painted in, its coverage goes up by k of the way to
    full (plus a little more near +1, so even poor spots fill); painted out,
    down like a Height fade (Coverage x (1 + k), the best spots thinning
    out too), none at -1."""
    if k > 0.0:
        return margin + k * (1.0 - cov) + 0.3 * k * k * k
    if k < 0.0:
        if k <= -0.999:
            return -1.0
        g = -k
        return margin - g * cov - 0.6 * g * g * g
    return margin


def sc_paint_of(layer):
    """The layer's paint for a build (_MiPaint), or None when nothing's painted."""
    paint = (layer or {}).get("paint")
    if not paint:
        return None
    mp = _MiPaint(paint)
    return mp if (mp.grid or mp.base) else None


# --------------------------------------------------------------- build
def _mi_drop_repeats(mesh):
    """A mesh without corners that repeat a vertex: a face's back-to-back
    repeats go (with their UVs), a face left with fewer than 3 corners or a
    repeat further round goes too (Maya drops such faces itself, and the UVs
    then no longer line up). The mesh itself when nothing repeats."""
    if not mesh or not mesh[1]:
        return mesh
    pts, counts, conn, us, vs, uvi = mesh
    it = iter(conn)  # each face's distinct corners, counted in C (a big shoots part has ~1M corners)
    if list(map(len, map(set, map(itertools.islice, itertools.repeat(it), counts)))) == list(counts):
        return mesh
    nc, ncon, nuv = [], [], []
    k = 0
    for c in counts:
        ids, uv = conn[k:k + c], uvi[k:k + c]
        k += c
        keep = [i for i in range(c) if ids[i] != ids[(i + 1) % c]]
        fi = [ids[i] for i in keep]
        if len(fi) < 3 or len(set(fi)) != len(fi):
            continue
        nc.append(len(fi))
        ncon.extend(fi)
        nuv.extend(uv[i] for i in keep)
    return (pts, nc, ncon, us, vs, nuv)


def _sc_build_layer(layer, surf, draft=False, rest_on=None, blocks=None):
    """A layer's parts {part: mesh} and counts, built on the surfaces (draft:
    a moss layer grows its quick look, "draft" in its counts; rest_on: what
    it lies on, [(mesh, lift, debris)]: the group's moss beds for leaves
    that Rest on moss, the layers below's debris (debris True) for On
    layers below (sc_build picks them); blocks: the group's blocker boxes, where nothing grows)."""
    typ = sc_type(layer.get("type"))
    s = sc_settings(layer)
    seeds = mi_seed_points(layer) or None
    faces = mi_face_mask(layer)
    strokes = sc_drawing(layer)
    draw = _MiDrawing(strokes, float(s["draw_width"]) / scene_m_per_unit(), s["draw_falloff"], s["draw_follow"],
                      surf.nodes) if strokes else None
    paint = sc_paint_of(layer)
    if blocks:
        paint = _ScBlocked(paint, blocks)
    counts = {}
    if typ == "Moss":
        ms = dict(MOSS_DEFAULTS)
        ms.update(s)
        out = moss_build(surf.nodes, ms, surf=surf, seeds=seeds, faces=faces, draw=draw, draft=draft, paint=paint,
                         instances=s.get("shoots", "Instances") == "Instances")
        parts = {p: out.get(p) for p, _ in SC_TYPES[typ]["parts"]}
        counts["clumps"] = out.get("clumps", 0)
        if out.get("shoots"):
            parts["shoots"] = out["shoots"]
            counts["shoots"] = len(out["shoots"][7]["pos"])
        if draft:
            counts["draft"] = True
    elif typ == "Ivy":
        ivs = dict(IVY_DEFAULTS)
        ivs.update(s)
        out = ivy_build(surf.nodes, ivs, seeds, surf=surf, draw=draw, paint=paint)
        parts = {p: out.get(p) for p, _ in SC_TYPES[typ]["parts"]}
        counts["vines"], counts["leaves"] = out.get("vines", 0), out.get("leaves_n", 0)
    else:
        ds = dict(DEBRIS_DEFAULTS)
        ds.update(s)
        for t2, key in SC_DEBRIS_ITEMS.items():
            if t2 != typ:
                ds[key] = 0.0
        if typ != "Grass":
            ds["grass_strays"] = 0.0
        out = debris_build(surf.nodes, ds, surf=surf, seeds=seeds, faces=faces, draw=draw, paint=paint,
                           rest_on=rest_on or None)
        parts = {part: out.get(src) for src, part in SC_DEBRIS_OUT[typ]}
        counts = {"bunches": out.get("bunches", 0), "leaves": out.get("leaves_n", 0), "piles": out.get("piles", 0),
                  "tufts": out.get("tufts_n", 0), "jungle": out.get("jungle_n", 0), "specks": out.get("specks_n", 0)}
    counts["capped"] = bool(out.get("capped"))
    return {p: (m if p == "shoots" else _mi_drop_repeats(m)) for p, m in parts.items()}, counts


def _sc_note(root):
    """What a group's parts were grown from, the first time this session
    touches it (a scene just opened): the JSON it was last grown from (a
    group from before that was stored: its settings, as saved) and its
    stamp."""
    if root in _SC_LAST or not is_scatter(root) or not cmds.attributeQuery(SC_STAMP, node=root, exists=True):
        return
    stamp = cmds.getAttr(root + "." + SC_STAMP) or ""
    if stamp:
        attr = SC_GROWN if cmds.attributeQuery(SC_GROWN, node=root, exists=True) else SC_ATTR
        _SC_LAST[root] = (cmds.getAttr(root + "." + attr), stamp)
        _SC_SURF.pop(root, None)
        if cmds.attributeQuery(SC_SURF, node=root, exists=True):
            try:
                _SC_SURF[root] = json.loads(cmds.getAttr(root + "." + SC_SURF) or "null")
            except ValueError:
                pass


def _sc_same_surf(a, b):
    """Two surface keys alike: the same meshes and counts, placed and sized
    the same to about 1e-4 (a scene saved and opened again rounds them)."""
    a, b = json.loads(json.dumps(a)), json.loads(json.dumps(b))
    if a is None or b is None or len(a) != len(b):
        return False
    for x, y in zip(a, b):
        if x[:3] != y[:3]:
            return False
        if any(abs(p - q) > 1e-4 * max(1.0, abs(p)) for p, q in zip(x[3] + x[4], y[3] + y[4])):
            return False
    return True


def _sc_set_text(root, attr, text):
    if not cmds.attributeQuery(attr, node=root, exists=True):
        cmds.addAttr(root, longName=attr, dataType="string")
    cmds.setAttr(root + "." + attr, text, type="string")


def _sc_grown_layers(root, data, skey):
    """{layer id: layer} of the on layers the group's parts show now (as
    last grown; {} when that's unknown, or its surfaces changed since: a
    mesh added to a surface group, or edited)."""
    _sc_note(root)
    known = _SC_SURF.get(root)
    if known is not None and not _sc_same_surf(known, skey):
        return {}
    last = _SC_LAST.get(root)
    if not last or not cmds.attributeQuery(SC_STAMP, node=root, exists=True) or \
            (cmds.getAttr(root + "." + SC_STAMP) or "") != last[1]:  # a redone new group: no parts yet
        return {}
    try:
        old = json.loads(last[0] or "{}")
    except ValueError:
        return {}
    if list(old.get("surfaces") or []) != list(data.get("surfaces") or []) or \
            list(old.get("exclude") or []) != list(data.get("exclude") or []):
        return {}
    return dict((l.get("id"), l) for l in old.get("layers", []) if l.get("on", True))


def _sc_read_part(node):
    """A part's mesh as it was written (world points, counts, vertex ids,
    us, vs, uv ids), or None."""
    shape = _log_shape(node)
    if not shape:
        return None
    fn = om.MFnMesh(get_dag_path(shape))
    us, vs = fn.getUVs()
    counts, conn = fn.getVertices()
    uvc, uvi = fn.getAssignedUVs()
    if not len(us) or list(uvc) != list(counts):
        return None
    pts = _mi_read_colors(fn, [(p.x, p.y, p.z) for p in fn.getPoints(om.MSpace.kWorld)])
    return pts, list(counts), list(conn), list(us), list(vs), list(uvi)


def _sc_read_layer(root, layer, counts):
    """An unchanged layer's parts read back from the scene (instead of
    growing it again), noted as written. Returns (parts, counts) or None."""
    parts = sc_parts(root)
    out, wrote = {}, {}
    for part, _ in SC_TYPES[sc_type(layer.get("type"))]["parts"]:
        key = layer["id"] + "/" + part
        node = parts.get(key)
        if node is None or not cmds.getAttr(node + ".visibility"):
            continue
        mesh = _sc_read_part(node)
        if mesh is None:
            return None
        out[part] = mesh
        wrote[(root, key)] = (id(mesh[0]), mesh[3][0], mesh[4][0], len(mesh[1]))
    node = sc_shoots(root).get(layer["id"] + "/shoots")
    if node is not None and cmds.getAttr(node + ".visibility"):
        got = _sc_read_shoots(node)
        if got is None:
            return None
        out["shoots"] = got
        wrote[(root, layer["id"] + "/shoots")] = _sc_shoots_sig(got)
    elif node is None and sc_type(layer.get("type")) == "Moss" and sc_settings(layer).get("shoots") == "Instances" \
            and "strands" in out:
        return None  # instanced shoots it should have aren't there (a Ctrl+D copy: they're in the control group)
    _SC_WROTE.update(wrote)
    c = dict(counts or {})
    c["read"] = True
    return out, c


def _sc_under_ids(layers, lid):
    """The on debris layers under layer lid in a list (what it lies on with
    On layers below): their ids, bottom up."""
    ids = [l.get("id") for l in layers]
    if lid not in ids:
        return ()
    return tuple(l.get("id") for l in reversed(layers[ids.index(lid) + 1:])
                 if l.get("on", True) and sc_type(l.get("type")) in SC_DEBRIS_ITEMS and
                 sc_type(l.get("type")) != "Specks")


def _sc_layer_core(layer):
    """A layer as its growth sees it: without its name or its own UDIM (UV
    placement only), so renaming it or moving it to other tiles never grows
    it again."""
    return dict((k, v) for k, v in layer.items() if k not in ("name", "udim"))


def _sc_place_udims(layers, combined, order, start):
    """Each part into its own UDIM tiles: layers with their own Start UDIM
    ("udim" on the layer; the user, 2026-11-12: "move one layer to a
    different UDIM than the rest of the group") first, in list order, from
    theirs, each on its own: two layers given the same UDIM overlap there
    (the user: "I should just be able to overlap two of them"); then the
    rest from the group's start, in list order, past every tile those take,
    so a layer following the group never shares a tile. Returns
    _roof_udims' output."""
    own = dict((l["id"], int(l["udim"])) for l in layers if l.get("udim") and l.get("on", True))
    placed, tiles, used = {}, {}, set()
    for layer in layers:
        lid = layer["id"]
        if lid not in own:
            continue
        o = [k for k in order if k.split("/")[0] == lid]
        got = _roof_udims(dict((k, combined[k]) for k in o if k in combined), own[lid], order=o)
        for k, ts in got.pop("udims").items():
            tiles[k] = ts
            used.update(ts)
        placed.update(got)
    o = [k for k in order if k.split("/")[0] not in own]
    got = _roof_udims(dict((k, m) for k, m in combined.items() if k.split("/")[0] not in own), start, order=o,
                      taken=used)
    tiles.update(got.pop("udims"))
    placed.update(got)
    placed["udims"] = tiles
    return placed


def sc_build(root, data, surf=None, only=None, readback=True, draft=None):
    """Every on layer's parts for a group, from the cache where a layer and
    its surfaces are unchanged (only: layer ids to rebuild regardless),
    else, when the parts in the scene show it as it is (a scene just
    opened), read back from them (readback=False: Regrow, grow them all),
    each part in its own UDIM tiles from the group's Start UDIM, in layer
    order. A layer that grows is a draft when Draft is on (draft: True /
    False overrides it); one that doesn't keeps what it is. Returns
    ({"<id>/<part>": mesh}, {"udims", counts..., "layers": {id: counts}},
    meshes)."""
    if draft is None:
        draft = _SC_DRAFT["on"]
    meshes = sc_surfaces(data)
    report = {"faces": 0, "capped": False, "clumps": 0, "vines": 0, "leaves": 0, "bunches": 0, "piles": 0,
              "tufts": 0, "jungle": 0, "specks": 0, "udims": {}, "surfaces": len(meshes), "layers": {}, "read": 0}
    combined, order = {}, []
    if not meshes:
        return combined, report, meshes
    surf = surf or _mi_surface(meshes)
    _mi_room(root, len(surf.nodes))
    skey = tuple(_mi_mesh_key(x) for x in surf.nodes)
    blocks = _sc_blocker_boxes(data)
    skey = skey + _sc_blocker_keys(blocks)  # a blocker moved or resized grows the layers again, like a surface
    report["skey"] = skey
    grown = _sc_grown_layers(root, data, skey) if readback else {}
    saved = {}
    if grown and cmds.attributeQuery(SC_COUNTS, node=root, exists=True):
        try:
            saved = json.loads(cmds.getAttr(root + "." + SC_COUNTS) or "{}")
        except ValueError:
            saved = {}
    layers = data.get("layers", [])
    for layer in layers:
        for part, _ in SC_TYPES[sc_type(layer.get("type"))]["parts"]:
            order.append(layer["id"] + "/" + part)  # UDIM tiles in list order
    # Grown bottom up (the user, 2026-11-12: "things higher up in the layer stack will appear on top"): moss
    # first wherever it is in the list (it grows on the surface itself), then the rest from the bottom of the
    # list to the top, so a debris layer that lies On layers below lands on what's under it in the list.
    seq = [l for l in layers if sc_type(l.get("type")) == "Moss"] + \
        [l for l in reversed(layers) if sc_type(l.get("type")) != "Moss"]
    rest, fresh = [], False  # the moss beds grown so far (Rest on moss), and whether one was grown just now
    below, fresh_below = [], False  # the debris of the layers grown so far (On layers below), the same
    for layer in seq:
        lid = layer["id"]
        typ = sc_type(layer.get("type"))
        if not layer.get("on", True):
            continue
        ls = sc_settings(layer)
        on_moss = typ in SC_DEBRIS_ITEMS and typ != "Grass" and bool(ls.get("on_moss")) and bool(rest)
        on_below = typ in SC_DEBRIS_ITEMS and bool(ls.get("on_layers")) and bool(below)
        ground = (list(rest) if on_moss else []) + (list(below) if on_below else [])
        # (not its name: renaming a layer grew it again; nor its own UDIM, which only moves its UVs)
        key = (root, lid, json.dumps(_sc_layer_core(layer), sort_keys=True), skey)
        if ground:  # leaves / grass that rest on what's under them rebuild when it changes
            key = key + (tuple((len(g[0][0]), len(g[0][1]), tuple(g[0][0][len(g[0][0]) // 2]) if g[0][0] else (),
                                g[1]) for g in ground),)
        hit = _SC_BUILT.get(key) if not (only and lid in only) else None
        if hit is None and lid in grown and _sc_layer_core(grown[lid]) == _sc_layer_core(layer) and \
                not (only and lid in only) and \
                not (on_moss and fresh) and not (on_below and fresh_below) and \
                not (on_below and _sc_under_ids(list(grown.values()), lid) != _sc_under_ids(layers, lid)):
            hit = _sc_read_layer(root, layer, saved.get(lid))
        if hit is None:
            kw = {"rest_on": ground} if ground else {}
            hit = _sc_build_layer(layer, surf, draft, blocks=blocks, **kw) if surf.items else ({}, {})
            fresh = fresh or typ == "Moss"
            fresh_below = fresh_below or typ in SC_DEBRIS_ITEMS
        if typ in SC_DEBRIS_ITEMS and typ != "Specks":
            below.extend((m, 0.0, True) for m in hit[0].values() if m and m[1])
        if typ == "Moss" and hit[0].get("moss") and hit[0]["moss"][1]:
            tall = MOSS_DETAIL.get(ls.get("detail"), MOSS_DETAIL["Normal"])[1] and float(ls.get("strands", 0)) > 0
            rest.append((hit[0]["moss"], 0.4 * float(ls.get("strand_length", 0.0)) / scene_m_per_unit()
                         if tall else 0.0))
        if hit is not _SC_BUILT.get(key):
            _SC_BUILT[key] = hit
            while len(_SC_BUILT) > 32:
                _SC_BUILT.popitem(last=False)
        parts, counts = hit
        report["layers"][lid] = dict((k, v) for k, v in counts.items() if k != "read")
        report["read"] += 1 if counts.get("read") else 0
        for part, mesh in parts.items():
            if mesh and mesh[1]:
                combined[lid + "/" + part] = mesh
        for k in ("clumps", "vines", "leaves", "bunches", "piles", "tufts", "jungle", "specks"):
            report[k] += counts.get(k, 0)
        report["capped"] = report["capped"] or counts.get("capped", False)
    # instanced shoots share their strands' tiles (one mossStrand texture): moved as the strands part moves,
    # or in its place when the layer has no strands part
    lone = {}
    for key in [k for k in combined if k.endswith("/shoots")]:
        strands = key[:-len("shoots")] + "strands"
        if strands not in combined:
            lone[strands] = key
            combined[strands] = combined.pop(key)
    before = dict((k, (min(m[3]), min(m[4]))) for k, m in combined.items() if k.endswith("/strands") and m[3])
    placed = _sc_place_udims(layers, combined, order, int(data.get("udim") or 1001))
    report["udims"] = placed.pop("udims")
    for strands, key in lone.items():
        placed[key] = placed.pop(strands)
        report["udims"][key] = report["udims"].pop(strands, [])
    for key in [k for k in placed if k.endswith("/shoots") and k[:-len("shoots")] + "strands" not in lone]:
        strands = key[:-len("shoots")] + "strands"
        if strands in before and strands in placed:
            du = int(math.floor(min(placed[strands][3]) + 1e-6)) - int(math.floor(before[strands][0] + 1e-6))
            dv = int(math.floor(min(placed[strands][4]) + 1e-6)) - int(math.floor(before[strands][1] + 1e-6))
            if du or dv:
                m = placed[key]
                placed[key] = tuple(m[:3]) + ([u + du for u in m[3]], [v + dv for v in m[4]]) + tuple(m[5:])
    return placed, report, meshes


# --------------------------------------------------------------- data
def is_scatter(node):
    """A live scatter group (not baked)."""
    return bool(node) and cmds.objExists(node) and cmds.attributeQuery(SC_ATTR, node=node, exists=True)


def _sc_attr(root):
    for attr in (SC_ATTR, SC_BAKED):
        if cmds.attributeQuery(attr, node=root, exists=True):
            return attr
    return None


def sc_data(root):
    """{"surfaces": [uuid], "exclude": [uuid], "udim", "layers": [{"id", "type", "tag", "name", "on", "s",
    "seeds", "faces"}]} (exclude: meshes / groups inside a surface group, left out of it)."""
    attr = _sc_attr(root)
    data = {}
    if attr:
        try:
            data = json.loads(cmds.getAttr(root + "." + attr) or "{}")
        except ValueError:
            data = {}
    data.setdefault("surfaces", [])
    data.setdefault("exclude", [])
    data.setdefault("layers", [])
    data.setdefault("udim", 1001)
    data.setdefault("next", 1 + len(data["layers"]))
    data["version"] = SC_VERSION
    return data


def sc_layer(data, lid):
    for layer in data.get("layers", []):
        if layer.get("id") == lid:
            return layer
    return None


def sc_groups(baked=False):
    """Every scatter group in the scene (baked ones too with baked=True)."""
    attrs = (SC_ATTR, SC_BAKED) if baked else (SC_ATTR,)
    found = []
    for attr in attrs:
        for node in cmds.ls(["*." + attr, "*:*." + attr], objectsOnly=True, long=True) or []:
            if node not in found and cmds.objectType(node, isAType="transform"):
                found.append(node)
    return found


def sc_parts(root):
    """{"<layer id>/<part>": transform} under a scatter group."""
    parts = {}
    for child in cmds.listRelatives(root, children=True, type="transform", fullPath=True) or []:
        shape = _log_shape(child)
        if shape and cmds.attributeQuery(SC_PART, node=shape, exists=True):
            parts[cmds.getAttr(shape + "." + SC_PART)] = child
    return parts


def sc_shoots(root):
    """{"<layer id>/shoots": transform}: a Moss layer's instanced shoots
    (particles, the instancer, its shoot shapes), in the group's control
    group (an older one still under the group itself)."""
    out = {}
    ctl = sc_control(root)
    for parent in ([ctl] if ctl else []) + [root]:
        for child in cmds.listRelatives(parent, children=True, type="transform", fullPath=True) or []:
            if cmds.attributeQuery(SC_SHOOTS, node=child, exists=True):
                key = cmds.getAttr(child + "." + SC_SHOOTS)
                if key not in out:
                    out[key] = child
    return out


def _sc_letters(i):
    """0 -> A, 25 -> Z, 26 -> AA ..."""
    s = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def _sc_shoot_names(node):
    """Names for what's under a shoots node <material><tag>Shoots####_GRP:
    (shapes group, shape name for index i, particle shape, instancer)."""
    m = re.match(r"^(.*?)(\d{4})_GRP$", short_name(node))
    base, num = (m.group(1), m.group(2)) if m else (short_name(node).replace("_GRP", ""), "")
    mat = base[:-len("Shoots")] if base.endswith("Shoots") else base
    return (base + "Shapes" + num + "_GRP", lambda i: "%s_C_shoot%s%s_GEP" % (mat, _sc_letters(i), num),
            base + "Points" + num + "Shape", base + num + "_INS")


def _sc_rename_shoots(node):
    """Give an older shoots node's insides the names _sc_shoot_names says."""
    grp_name, shape_name, ps_name, inst_name = _sc_shoot_names(node)
    ps, inst, shapes = _sc_shoot_nodes(node)
    for i, xf in enumerate(shapes):
        if short_name(xf) != shape_name(i):
            cmds.rename(xf, shape_name(i))
    for child in cmds.listRelatives(node, children=True, fullPath=True) or []:
        if cmds.nodeType(child) == "transform" and short_name(child) != grp_name:
            cmds.rename(child, grp_name)
    ps, inst, _ = _sc_shoot_nodes(node)
    if ps and short_name(ps) != ps_name:
        cmds.rename(ps, ps_name)
    if inst and short_name(inst) != inst_name:
        cmds.rename(inst, inst_name)


def _sc_shoot_nodes(node):
    """(particle shape, instancer, [shape meshes in index order]) under a shoots transform."""
    ps = (cmds.listRelatives(node, shapes=True, type="particle", fullPath=True) or [None])[0]
    inst = (cmds.listRelatives(node, children=True, type="instancer", fullPath=True) or [None])[0]
    shapes = []
    for grp in cmds.listRelatives(node, children=True, type="transform", fullPath=True) or []:
        if cmds.nodeType(grp) != "transform":
            continue  # (the instancer)
        for child in cmds.listRelatives(grp, children=True, type="transform", fullPath=True) or []:
            sh = _log_shape(child)
            if sh and cmds.attributeQuery(SC_SHOOT_SHAPE, node=sh, exists=True):
                shapes.append((cmds.getAttr(sh + "." + SC_SHOOT_SHAPE), child))
    return ps, inst, [c for _, c in sorted(shapes)]


def _sc_shoots_sig(mesh):
    return (id(mesh[0]), id(mesh[7]["pos"]), mesh[3][0] if mesh[3] else 0.0, len(mesh[7]["pos"]), len(mesh[6]))


def _sc_sg(node):
    shape = _log_shape(node) if node and cmds.objExists(node) else None
    sgs = cmds.listConnections(shape, type="shadingEngine") or [] if shape else []
    return sgs[0] if sgs else None


def _sc_under(parent, name):
    """The full path of a node just made / parented under parent (full
    path, or None: world) by the name Maya returned. Not long_name: a Ctrl+D
    copy's rig has the same names as the original's, and looking one up by
    name can find the original's (the copy's instances went into it)."""
    return (parent or "") + "|" + short_name(name)


def _sc_make_shoots(root, layer, material):
    """A Moss layer's instanced shoots node (outside the undo queue), in
    the group's control group (not published: an instancer isn't plain
    geometry): <material><tag>Shoots####_GRP, tagged."""
    num = short_name(root)[len(SC_STEM):len(SC_STEM) + 4]
    parent = sc_control(root) or root
    node = _sc_under(parent, cmds.createNode("transform", name="%s%sShoots%s_GRP" % (
        material, layer.get("tag", ""), num), parent=parent, skipSelect=True))
    cmds.addAttr(node, longName=SC_SHOOTS, dataType="string")
    cmds.setAttr(node + "." + SC_SHOOTS, layer["id"] + "/shoots", type="string")
    return node


def _sc_fill_shoots(node, mesh, sg=None):
    """(Re)make what's under a shoots node from moss_shoot_instances'
    mesh: the shoot shapes (hidden, UV ready / stacked, the strands' shading
    or what they had), a particle shape holding each shoot's place, turn and
    length (saved with the scene as its initial state, not dynamic) and an
    instancer of the shapes. Returns the faces the instances make."""
    import maya.OpenMayaFX as omfx1
    pts, counts, conn, us, vs, uvi, split, data = mesh
    old = _sc_shoot_nodes(node)
    sg = sg or (_sc_sg(old[2][0]) if old[2] else None)
    kids = cmds.listRelatives(node, children=True, fullPath=True) or []
    if kids:
        cmds.delete(kids)
    grp_name, shape_name, ps_name, inst_name = _sc_shoot_names(node)
    grp = _sc_under(node, cmds.createNode("transform", name=grp_name, parent=node, skipSelect=True))
    cmds.setAttr(grp + ".visibility", False)
    shapes = []
    n0 = f0 = k0 = 0
    for i, (n, f, k) in enumerate(split):
        sub = (pts[n0:n0 + n], counts[f0:f0 + f], [c - n0 for c in conn[k0:k0 + k]], us[n0:n0 + n], vs[n0:n0 + n],
               [c - n0 for c in uvi[k0:k0 + k]])
        n0, f0, k0 = n0 + n, f0 + f, k0 + k
        xf = long_name(cmds.polyPlane(width=1, height=1, subdivisionsX=1, subdivisionsY=1,
                                      constructionHistory=False, name=shape_name(i))[0])
        xf = _sc_under(grp, cmds.parent(xf, grp)[0])
        sh = _log_shape(xf)
        cmds.addAttr(sh, longName=SC_SHOOT_SHAPE, attributeType="long", defaultValue=i)
        cmds.addAttr(sh, longName=UV_READY_ATTR, attributeType="bool", defaultValue=True)
        cmds.addAttr(sh, longName=UV_STACKED_ATTR, attributeType="bool", defaultValue=True)
        _rope_fill(sh, sub)
        if sg and cmds.objExists(sg):
            cmds.sets(sh, edit=True, forceElement=sg)
        shapes.append(xf)
    # a name no other node has until it's filled and instanced: MFnParticleSystem.emit and the instancer go
    # by name, and a Ctrl+D copy's rig has the original's names (its instances went into the original's)
    ps = _sc_under(node, cmds.createNode("particle", name="unlokShootPointsTmp#", parent=node, skipSelect=True))
    for ln, typ in (("rotationPP", "vectorArray"), ("scalePP", "vectorArray"), ("indexPP", "doubleArray")):
        cmds.addAttr(ps, longName=ln, dataType=typ)
        cmds.addAttr(ps, longName=ln + "0", dataType=typ)
    sel = om1.MSelectionList()
    sel.add(ps)
    obj = om1.MObject()
    sel.getDependNode(0, obj)
    fn = omfx1.MFnParticleSystem(obj)
    arr = om1.MPointArray()
    for p in data["pos"]:
        arr.append(om1.MPoint(p[0], p[1], p[2]))
    fn.emit(arr)
    rot, sca, idx = om1.MVectorArray(), om1.MVectorArray(), om1.MDoubleArray()
    for r in data["rot"]:
        rot.append(om1.MVector(r[0], r[1], r[2]))
    for L in data["scale"]:
        sca.append(om1.MVector(L, L, L))
    for i in data["index"]:
        idx.append(float(i))
    fn.setPerParticleAttribute("rotationPP", rot)
    fn.setPerParticleAttribute("scalePP", sca)
    fn.setPerParticleAttribute("indexPP", idx)
    fn.saveInitialState()
    cmds.setAttr(ps + ".isDynamic", False)
    cmds.setAttr(ps + ".visibility", False)  # the points themselves: only the instances show
    inst = cmds.particleInstancer(ps, addObject=True, object=shapes, cycle="None", rotation="rotationPP",
                                  scale="scalePP", objectIndex="indexPP", rotationUnits="Degrees")
    inst = cmds.parent(inst, node)[0]
    inst = cmds.rename(_sc_under(node, inst), inst_name)
    cmds.rename(ps, ps_name)
    _sc_shoots_order(node)
    per = [f for _, f, _ in split]
    return sum(per[i] for i in data["index"])


def _sc_shoots_order(node):
    """The instancer first under a shoots node. Maya frees a deleted
    hierarchy's nodes in child order: with the particle shape first, the
    instancer was left copying a freed particle's points and Maya crashed
    (a group grown, Ctrl+Z, Ctrl+Y, Ctrl+Z, then any command)."""
    kids = cmds.listRelatives(node, children=True, fullPath=True) or []
    inst = [k for k in kids if cmds.nodeType(k) == "instancer"]
    if inst and kids[0] != inst[0]:
        cmds.reorder(inst[0], front=True)


def _sc_read_shoots(node):
    """A shoots node read back as moss_shoot_instances' mesh, or None."""
    import maya.OpenMayaFX as omfx1
    ps, inst, shapes = _sc_shoot_nodes(node)
    if not ps or not inst or not shapes:
        return None
    mesh, split = _mi_mesh(), []
    for xf in shapes:
        sub = _sc_read_part(xf)
        if sub is None:
            return None
        b = len(mesh[0])
        mesh[0].extend(sub[0])
        mesh[1].extend(sub[1])
        mesh[2].extend(c + b for c in sub[2])
        mesh[3].extend(sub[3])
        mesh[4].extend(sub[4])
        mesh[5].extend(c + b for c in sub[5])
        split.append((len(sub[0]), len(sub[1]), len(sub[2])))
    sel = om1.MSelectionList()
    sel.add(ps)
    obj = om1.MObject()
    sel.getDependNode(0, obj)
    fn = omfx1.MFnParticleSystem(obj)
    pos, rot, sca, idx = om1.MVectorArray(), om1.MVectorArray(), om1.MVectorArray(), om1.MDoubleArray()
    fn.position(pos)
    fn.getPerParticleAttribute("rotationPP", rot)
    fn.getPerParticleAttribute("scalePP", sca)
    fn.getPerParticleAttribute("indexPP", idx)
    n = pos.length()
    if rot.length() != n or sca.length() != n or idx.length() != n:
        return None
    data = {"pos": [(pos[i].x, pos[i].y, pos[i].z) for i in range(n)],
            "rot": [(rot[i].x, rot[i].y, rot[i].z) for i in range(n)],
            "scale": [sca[i].x for i in range(n)], "index": [int(round(idx[i])) for i in range(n)]}
    data["axes"] = [_mi_axes_xyz(*r) for r in data["rot"]]
    return tuple(mesh) + (split, data)


def sc_box(root):
    """A group's box: beside it, linked both ways by uuid (an old one still
    inside it). None when it's been deleted, or it's a Ctrl+D copy's link
    to the original's box (sc_fix_box gives a copy its own)."""
    if cmds.attributeQuery(SC_BOX_ID, node=root, exists=True):
        uid = cmds.getAttr(root + "." + SC_BOX_ID)
        found = cmds.ls(uid, long=True) if uid else None
        if found and _sc_box_of(found[0]) == cmds.ls(root, uuid=True)[0]:
            return found[0]
    for child in cmds.listRelatives(root, children=True, type="transform", fullPath=True) or []:
        if cmds.attributeQuery(SC_BOX_ATTR, node=child, exists=True):
            return child
    return None


def sc_control(root):
    """A group's control group (scatterControl####_GRP: its box, instanced
    shoots, anything that isn't plain geometry to publish), linked both
    ways by uuid; None when there's none yet (sc_fix_box makes it) or the
    link is a Ctrl+D copy's to the original's."""
    if root and cmds.attributeQuery(SC_CTL_ID, node=root, exists=True):
        uid = cmds.getAttr(root + "." + SC_CTL_ID)
        found = cmds.ls(uid, long=True) if uid else None
        if found and _sc_ctl_of(found[0]) == cmds.ls(root, uuid=True)[0]:
            return found[0]
    return None


def _sc_ctl_of(node):
    """The uuid of the group a control group belongs to, or ""."""
    if cmds.attributeQuery(SC_CTL, node=node, exists=True):
        return cmds.getAttr(node + "." + SC_CTL) or ""
    return ""


def _sc_link_control(root, ctl):
    for node, attr, other in ((root, SC_CTL_ID, ctl), (ctl, SC_CTL, root)):
        if not cmds.attributeQuery(attr, node=node, exists=True):
            cmds.addAttr(node, longName=attr, dataType="string")
        cmds.setAttr(node + "." + attr, cmds.ls(other, uuid=True)[0], type="string")


def _sc_make_control(root, box=None, auto=False):
    """A control group for a group, beside its box (under the box's parent;
    at world level without one; beside another group's control group when
    the box is a copy made in that one), linked to it."""
    m = re.match(SC_STEM + r"(\d{4})", short_name(root))
    num = int(m.group(1)) if m else _th_free_number(SC_CTL_STEM + "%04d_GRP")
    parent = (cmds.listRelatives(box, parent=True, fullPath=True) or [None])[0] if box else None
    while parent and cmds.attributeQuery(SC_CTL, node=parent, exists=True):  # never one inside another
        parent = (cmds.listRelatives(parent, parent=True, fullPath=True) or [None])[0]
    kw = {"parent": parent} if parent else {}
    ctl = _sc_under(parent, cmds.createNode("transform", name="%s%04d_GRP" % (SC_CTL_STEM, num), skipSelect=True,
                                            **kw))
    if auto:
        cmds.addAttr(ctl, longName=SC_CTL_AUTO, attributeType="bool", defaultValue=True)
    _sc_link_control(root, ctl)
    return ctl


def _sc_fix_control(root, box):
    """Bring a group's control setup up to date (inside sc_fix_box's
    NoUndo): its control group (adopting a Ctrl+D copy's copy, else a new
    one beside the box), the box in it, older instanced shoots moved out
    of the group into it (renamed), and hidden parts (emptied, from before
    empty parts were deleted) deleted. The group's geometry stays where it
    is. Returns the control group."""
    ctl = sc_control(root)
    fresh = ctl is None  # the box goes in when its control group is made / adopted (moved out later: left)
    if ctl is None:
        par = (cmds.listRelatives(box, parent=True, fullPath=True) or [None])[0] if box else None
        if par and cmds.attributeQuery(SC_CTL, node=par, exists=True):
            other = cmds.ls(_sc_ctl_of(par) or "-", long=True)
            if not other or other[0] == root or sc_control(other[0]) != par:  # a copy made with it: its own
                ctl = par
                _sc_link_control(root, ctl)
        if ctl is None:
            copy = cmds.attributeQuery(SC_CTL_ID, node=root, exists=True)
            ctl = _sc_make_control(root, box, auto=bool(copy))
    if fresh and box and (cmds.listRelatives(box, parent=True, fullPath=True) or [None])[0] != ctl:
        box = long_name(cmds.parent(box, ctl)[0])
    for child in cmds.listRelatives(root, children=True, type="transform", fullPath=True) or []:
        if cmds.attributeQuery(SC_SHOOTS, node=child, exists=True):  # older shoots: into the control group
            if not cmds.getAttr(child + ".visibility"):
                cmds.delete(child)
                continue
            name = short_name(child).replace("_C_" + SC_STEM, "")
            child = long_name(cmds.parent(child, ctl)[0])
            if short_name(child) != name:
                child = long_name(cmds.rename(child, name))
            _sc_rename_shoots(child)
            continue
        shape = _log_shape(child)
        if shape and cmds.attributeQuery(SC_PART, node=shape, exists=True) and \
                not cmds.getAttr(child + ".visibility"):  # an emptied part, hidden by an older toolbox
            _SC_WROTE.pop((root, cmds.getAttr(shape + "." + SC_PART)), None)
            cmds.delete(child)
    for key, node in sc_shoots(root).items():
        if not cmds.getAttr(node + ".visibility"):
            cmds.delete(node)
    return ctl


def _sc_box_of(box):
    """The uuid of the group a box belongs to ("" for an old box: its parent)."""
    if cmds.attributeQuery(SC_BOX_OF, node=box, exists=True):
        return cmds.getAttr(box + "." + SC_BOX_OF) or ""
    return ""


def _sc_link_box(root, box):
    """Link a group and its box both ways by uuid."""
    for node, attr, other in ((root, SC_BOX_ID, box), (box, SC_BOX_OF, root)):
        if not cmds.attributeQuery(attr, node=node, exists=True):
            cmds.addAttr(node, longName=attr, dataType="string")
        cmds.setAttr(node + "." + attr, cmds.ls(other, uuid=True)[0], type="string")


def _sc_make_box(root, auto=False):
    """A wireframe box for a group, at world level, linked to it (fit it
    after). auto: made outside the undo queue (sc_sync deletes it when its
    group is gone, say the Ctrl+D it was made for is undone)."""
    m = re.match(SC_STEM + r"(\d{4})", short_name(root))
    num = int(m.group(1)) if m else _th_free_number(SC_STEM + "%04d_CTL")
    box = long_name(cmds.polyCube(width=1, height=1, depth=1, constructionHistory=False,
                                  name="%s%04d_CTL" % (SC_STEM, num))[0])
    shape = _log_shape(box)
    cmds.addAttr(box, longName=SC_BOX_ATTR, attributeType="bool", defaultValue=True)
    if auto:
        cmds.addAttr(box, longName=SC_BOX_AUTO, attributeType="bool", defaultValue=True)
    for attr in ("castsShadows", "receiveShadows", "primaryVisibility", "visibleInReflections",
                 "visibleInRefractions"):
        if cmds.attributeQuery(attr, node=shape, exists=True):
            cmds.setAttr(shape + "." + attr, False)
    cmds.setAttr(box + ".overrideEnabled", True)
    cmds.setAttr(box + ".overrideShading", False)  # wireframe: click its edges to pick the group
    _sc_link_box(root, box)
    return box


def sc_fix_box(root):
    """Bring a group up to date, outside the undo queue (the first time
    the toolbox touches it: the panel picks it, it regrows): its move /
    rotate / scale unlocked (locked, Maya can't keep it in place when it's
    dragged under a moved group), an old box inside it moved out beside it
    (where it is), a Ctrl+D copy (its link is the original's box) given a
    box of its own (a copy of the box made with it, else a new one round
    it). Returns its box, or None (deleted: Make Box)."""
    if not is_scatter(root):
        return None
    with NoUndo():
        for attr in ("translate", "rotate", "scale"):
            for ax in "XYZ":
                if cmds.getAttr(root + "." + attr + ax, lock=True):
                    cmds.setAttr(root + "." + attr + ax, lock=False)
        box = sc_box(root)
        if box and not _sc_box_of(box):  # an old box inside the group: out beside it
            sel = cmds.ls(selection=True, long=True) or []
            box = long_name(cmds.parent(box, world=True)[0])
            _sc_link_box(root, box)
            _sc_reselect(sel, box)
        elif not box and cmds.attributeQuery(SC_BOX_ID, node=root, exists=True):
            uid = cmds.getAttr(root + "." + SC_BOX_ID)
            found = cmds.ls(uid, long=True) if uid else None
            other = _sc_box_of(found[0]) if found else ""
            if other and cmds.ls(other) and other != cmds.ls(root, uuid=True)[0]:  # a copy
                sel = cmds.ls(selection=True, long=True) or []
                spare = [b for b in _sc_boxes() if b != found[0] and _sc_box_of(b) == other]
                if spare:  # the group and its box were copied together: that copy is its box
                    box = spare[0]
                    _sc_link_box(root, box)
                else:
                    box = _sc_make_box(root, auto=True)
                    _sc_fit_box(root, box, sc_surfaces(sc_data(root)))
                _sc_reselect(sel, box)
        if not _sc_control_ok(root, box):
            sel = cmds.ls(selection=True, long=True) or []
            _sc_fix_control(root, box)
            box = sc_box(root)
            _sc_reselect([s for s in sel if cmds.objExists(s)], box)
    return box


def _sc_control_ok(root, box):
    """The group's control setup is as _sc_fix_control leaves it (a quick
    check, so picking a group doesn't walk it every time)."""
    if sc_control(root) is None:
        return False
    for child in cmds.listRelatives(root, children=True, type="transform", fullPath=True) or []:
        if cmds.attributeQuery(SC_SHOOTS, node=child, exists=True) or not cmds.getAttr(child + ".visibility"):
            return False
    return True


def _sc_reselect(sel, box):
    """Put back the selection a box's parent / polyCube changed (the moved
    box under its new name)."""
    sel = [box if s.endswith("_CTL") and not cmds.objExists(s) else s for s in sel]
    sel = [s for s in sel if cmds.objExists(s)]
    if sel:
        cmds.select(sel, replace=True)
    else:
        cmds.select(clear=True)


def _sc_boxes():
    """Every scatter box in the scene."""
    return [n for n in cmds.ls(["*." + SC_BOX_ATTR, "*:*." + SC_BOX_ATTR], objectsOnly=True, long=True) or []
            if cmds.objectType(n, isAType="transform")]


def _sc_drop_orphan_boxes():
    """Delete boxes made outside the undo queue whose group is gone (the
    Ctrl+D copy they were made for was undone). Returns how many."""
    gone = [b for b in _sc_boxes() if cmds.attributeQuery(SC_BOX_AUTO, node=b, exists=True) and
            not cmds.ls(_sc_box_of(b) or "-")]
    ctls = [n for n in cmds.ls(["*." + SC_CTL_AUTO, "*:*." + SC_CTL_AUTO], objectsOnly=True, long=True) or []
            if not cmds.ls(_sc_ctl_of(n) or "-")]
    gone = [b for b in gone if not _under_any(b, ctls)] + ctls
    if gone:
        with NoUndo():
            cmds.delete(gone)
    return len(gone)


def sc_remake_boxes(roots):
    """Give groups whose box is gone (deleted, say, to keep it out of a
    publish) a box again, round what they grew. One Ctrl+Z; the new boxes
    are selected. Returns [(root, box)] (groups with a box are left alone)."""
    roots = [r for r in roots if is_scatter(r) and not sc_fix_box(r)]
    made = []
    if not roots:
        return made
    with UndoChunk("Scatter box"):
        for root in roots:
            box = _sc_make_box(root)
            ctl = sc_control(root)
            if ctl:
                box = long_name(cmds.parent(box, ctl)[0])
            _sc_fit_box(root, box, sc_surfaces(sc_data(root)))
            made.append((root, box))
        cmds.select([b for _, b in made], replace=True)
    return made


def sc_owner(node):
    """(group, layer id or None) a node belongs to: the group itself, its
    box, or one of its parts (then its layer). (None, None) otherwise."""
    if not node or not cmds.objExists(node):
        return None, None
    node = long_name(node)
    if cmds.objectType(node, isAType="shape"):
        node = long_name(cmds.listRelatives(node, parent=True, fullPath=True)[0])
    if _sc_attr(node):
        return node, None
    if _sc_box_of(node):  # a box beside its group
        found = cmds.ls(_sc_box_of(node), long=True)
        return (found[0], None) if found and _sc_attr(found[0]) else (None, None)
    if _sc_ctl_of(node):  # a control group
        found = cmds.ls(_sc_ctl_of(node), long=True)
        return (found[0], None) if found and _sc_attr(found[0]) else (None, None)
    if _sc_blocker_of(node):  # a blocker box the tool made picks its group
        found = cmds.ls(_sc_blocker_of(node), long=True)
        return (found[0], None) if found and _sc_attr(found[0]) else (None, None)
    up = node
    for _ in range(3):  # instanced shoots: the instancer, the shapes' group, a shape under their node
        if cmds.attributeQuery(SC_SHOOTS, node=up, exists=True):
            parent = cmds.listRelatives(up, parent=True, fullPath=True)
            lid = cmds.getAttr(up + "." + SC_SHOOTS).split("/")[0]
            if parent and _sc_attr(parent[0]):
                return parent[0], lid
            if parent and _sc_ctl_of(parent[0]):  # in a control group
                found = cmds.ls(_sc_ctl_of(parent[0]), long=True)
                if found and _sc_attr(found[0]):
                    return found[0], lid
            break
        nxt = cmds.listRelatives(up, parent=True, fullPath=True)
        if not nxt:
            break
        up = nxt[0]
    parent = cmds.listRelatives(node, parent=True, fullPath=True)
    if not parent or not _sc_attr(parent[0]):
        return None, None
    if cmds.attributeQuery(SC_BOX_ATTR, node=node, exists=True):
        return parent[0], None
    shape = _log_shape(node)
    if shape and cmds.attributeQuery(SC_PART, node=shape, exists=True):
        return parent[0], cmds.getAttr(shape + "." + SC_PART).split("/")[0]
    return None, None


def sc_surfaces(data):
    """The meshes a group scatters onto, now: each stored mesh, and every
    visible mesh under each stored group (meshes added to it later too)
    but the ones left out of it (exclude: a mesh, or a group inside it),
    never anything inside a scatter group."""
    groups = [g + "|" for g in sc_groups(baked=True)]
    blockers = sc_blockers(data)  # a blocker is never grown on
    left_out = _sc_left_out(data) + blockers
    out = []
    for uid in data.get("surfaces") or []:
        found = cmds.ls(uid, long=True) or []
        if not found:
            continue
        node = found[0]
        if _log_shape(node):
            cand = [node]
        else:
            shapes = cmds.listRelatives(node, allDescendents=True, type="mesh", fullPath=True,
                                        noIntermediate=True) or []
            cand = []
            for sh in cmds.ls(shapes, visible=True, long=True) or []:
                if cmds.attributeQuery(SC_PART, node=sh, exists=True):  # baked scatter moved in: added only by hand
                    continue
                t = cmds.listRelatives(sh, parent=True, fullPath=True)[0]
                if cmds.attributeQuery(SC_BOX_ATTR, node=t, exists=True) or \
                        cmds.attributeQuery(SC_BLOCKER_ATTR, node=t, exists=True):  # a box / blocker moved in
                    continue
                if t not in cand and not _sc_inside(t, left_out):
                    cand.append(t)
        for t in cand:
            if t not in out and not any((t + "|").startswith(g) for g in groups) and \
                    not (blockers and _sc_inside(t, blockers)):
                out.append(t)
    return out


def _sc_left_out(data):
    """Long names of what's left out of the group's surface groups."""
    out = []
    for uid in data.get("exclude") or []:
        out.extend(cmds.ls(uid, long=True) or [])
    return out


def _sc_inside(node, under):
    """True when node is one of under or below one of them."""
    return any(node == u or node.startswith(u + "|") for u in under)


def _sc_covering(data, node):
    """The stored group a node is inside (it's scattered onto through it), else None."""
    for uid in data.get("surfaces") or []:
        found = cmds.ls(uid, long=True) or []
        if found and not _log_shape(found[0]) and node.startswith(found[0] + "|"):
            return found[0]
    return None


def _sc_include(data, node):
    """node is scattered onto: back in its surface group when it was left
    out of it, else (not in one, or inside something left out, or a
    scatter part, which a surface group never uses by itself) a surface of
    its own."""
    uid = cmds.ls(node, uuid=True)[0]
    ex = data.setdefault("exclude", [])
    if uid in ex:
        ex.remove(uid)
    shape = _log_shape(node)
    part = bool(shape) and cmds.attributeQuery(SC_PART, node=shape, exists=True)
    if not part and _sc_covering(data, node) and not _sc_inside(node, _sc_left_out(data)):
        return
    if uid not in data["surfaces"]:
        data["surfaces"].append(uid)


def _sc_exclude(data, node):
    """node isn't scattered onto: its own entry goes, and when it's inside
    a surface group it's left out of that group (the group stays)."""
    uid = cmds.ls(node, uuid=True)[0]
    if uid in data["surfaces"]:
        data["surfaces"].remove(uid)
    ex = data.setdefault("exclude", [])
    if uid not in ex and _sc_covering(data, node) and not _sc_inside(node, _sc_left_out(data)):
        ex.append(uid)
    # what's left out of a group that's gone (or was deleted) is forgotten
    data["exclude"] = [u for u in ex if any(_sc_covering(data, n) for n in cmds.ls(u, long=True) or [])]


def sc_area(layer):
    """(picked points, picked face count, strokes drawn) of a layer."""
    return (len(layer.get("seeds") or []), sum(len(v) for v in (layer.get("faces") or {}).values()),
            len((layer.get("draw") or {}).get("k") or []))


# --------------------------------------------------------------- scene
def _sc_set(root, data):
    cmds.setAttr(root + "." + SC_ATTR, json.dumps(data, sort_keys=True), type="string")


def _sc_make_part(root, layer, part, material):
    """A part mesh for a layer (outside the undo queue, like its geometry):
    a seed plane, tagged, named <material><tag>_C_scatteredObjects####_GEP."""
    num = short_name(root)[len(SC_STEM):len(SC_STEM) + 4]
    name = "%s%s_C_%s%s_GEP" % (material, layer.get("tag", ""), SC_STEM, num)
    node = long_name(cmds.polyPlane(width=1, height=1, subdivisionsX=1, subdivisionsY=1, constructionHistory=False,
                                    name=name)[0])
    node = long_name(cmds.parent(node, root)[0])
    shape = _log_shape(node)
    cmds.addAttr(shape, longName=SC_PART, dataType="string")
    cmds.setAttr(shape + "." + SC_PART, layer["id"] + "/" + part, type="string")
    cmds.addAttr(shape, longName=MI_VERTS, attributeType="long", defaultValue=0)
    cmds.addAttr(shape, longName=UV_READY_ATTR, attributeType="bool", defaultValue=True)
    if part in MI_STACKED_PARTS or part in ("piles", "green", "dry", "specks", "dirt"):
        cmds.addAttr(shape, longName=UV_STACKED_ATTR, attributeType="bool", defaultValue=True)
    return node


def _sc_fit_box(root, box, meshes):
    """The box round what the group grew (else round its surfaces)."""
    nodes = [n for n in sc_parts(root).values() if cmds.getAttr(n + ".visibility")] or meshes
    if not box or not nodes:
        return
    bb = cmds.exactWorldBoundingBox(nodes)
    size = [max(bb[k + 3] - bb[k], 1e-3) * 1.02 for k in range(3)]
    for ax, v in zip("xyz", ((bb[0] + bb[3]) * 0.5, (bb[1] + bb[4]) * 0.5, (bb[2] + bb[5]) * 0.5)):
        cmds.setAttr("%s.translate%s" % (box, ax.upper()), v)
    for ax, v in zip("XYZ", size):
        cmds.setAttr("%s.scale%s" % (box, ax), v)
    for ax in "XYZ":
        cmds.setAttr("%s.rotate%s" % (box, ax), 0.0)


def _sc_write(root, data, placed, meshes):
    """Put built parts in the group's meshes (outside the undo queue):
    makes a part the first time it has something, deletes one that's
    empty now (hidden leftovers went wherever the group was dragged, into
    publishes: the user, 2026-11-09), rewrites only what changed. Returns
    the face count."""
    parts = sc_parts(root)
    shoots = sc_shoots(root)
    faces = 0
    sel = cmds.ls(selection=True, long=True) or []  # making parts / instancers selects them: put it back after
    for layer in data.get("layers", []):
        for part, material in SC_TYPES[sc_type(layer.get("type"))]["parts"]:
            key = layer["id"] + "/" + part
            mesh = placed.get(key)
            node = parts.get(key)
            if not mesh:
                if node:
                    cmds.delete(node)
                    _SC_WROTE.pop((root, key), None)
                continue
            if node is None:
                node = _sc_make_part(root, layer, part, material)
            if part == "moss" and sc_type(layer.get("type")) == "Moss":
                node = parts[key] = _sc_bed_suffix(node, sc_settings(layer))
            sig = (id(mesh[0]), mesh[3][0] if mesh[3] else 0.0, mesh[4][0] if mesh[4] else 0.0, len(mesh[1]))
            shape = _log_shape(node)
            if _SC_WROTE.get((root, key)) != sig or cmds.getAttr(shape + "." + MI_VERTS) != len(mesh[0]):
                cmds.setAttr(shape + "." + MI_VERTS, _rope_fill(shape, mesh))
                _mi_write_colors(shape, mesh)  # shading data (moss)
                _SC_WROTE[(root, key)] = sig
            if not cmds.getAttr(node + ".visibility"):
                cmds.setAttr(node + ".visibility", True)
            faces += len(mesh[1])
        if sc_type(layer.get("type")) == "Moss":
            faces += _sc_write_layer_shoots(root, layer, placed, shoots, parts)
    known = set(l["id"] for l in data.get("layers", []))
    for key, node in list(parts.items()) + list(shoots.items()):  # a layer that's gone (a safety net)
        if key.split("/")[0] not in known and cmds.objExists(node):
            cmds.delete(node)
            _SC_WROTE.pop((root, key), None)
    _sc_fit_box(root, sc_box(root), meshes)
    now = cmds.ls(selection=True, long=True) or []
    if now != sel:  # polyPlane / parent / particleInstancer select what they make: keep what was selected
        sel = [n for n in sel if cmds.objExists(n)]
        if sel:
            cmds.select(sel, replace=True)
        else:
            cmds.select(clear=True)
    return faces


MOSS_LOOK_PARTS = {"moss": "mossGreen", "strands": "mossStrand", "capsules": "mossSpore"}


def _ml_node(kind, name, shader=False, **attrs):
    n = cmds.shadingNode(kind, asShader=shader, asTexture=not shader, name=name, skipSelect=True)
    for k, v in attrs.items():
        if not cmds.attributeQuery(k, node=n, exists=True):
            continue
        if isinstance(v, (tuple, list)):
            cmds.setAttr(n + "." + k, *v, type="double3")
        elif isinstance(v, str):
            cmds.setAttr(n + "." + k, v, type="string")
        else:
            cmds.setAttr(n + "." + k, v)
    return n


def _ml_noise(name, size, c1, c2, octaves=3, distortion=0.0):
    """aiNoise in world space with features about size metres across."""
    k = scene_m_per_unit() / max(1e-6, size)
    return _ml_node("aiNoise", name, octaves=octaves, distortion=distortion, coordSpace=0, scale=(k, k, k),
                    color1=c1, color2=c2)


def _ml_range(name, src, lo, hi, out_lo=0.0, out_hi=1.0):
    r = _ml_node("aiRange", name, inputMin=lo, inputMax=hi, outputMin=out_lo, outputMax=out_hi, smoothstep=1)
    if src.endswith(("R", "G", "B")) and not src.endswith("outColor"):
        for ch in "RGB":
            cmds.connectAttr(src, r + ".input" + ch, force=True)
    else:
        cmds.connectAttr(src, r + ".input", force=True)
    return r


def _ml_layer(name, base, top, mix):
    """aiLayerRgba: top (an attribute or an rgb) over base by mix."""
    n = _ml_node("aiLayerRgba", name, enable1=1, enable2=1)
    for slot, v in (("input1", base), ("input2", top)):
        if isinstance(v, str):
            cmds.connectAttr(v, n + "." + slot, force=True)
        else:
            cmds.setAttr(n + "." + slot, *v, type="double3")
    cmds.connectAttr(mix, n + ".mix2", force=True)
    return n


def _ml_data(name, default=(0.5, 1.0, 1.0)):
    """The moss shading data (MOSS_COLOR_SET) as Arnold user data; default
    where a mesh has none (an older moss: no edge or height shading)."""
    return _ml_node("aiUserDataColor", name, attribute=MOSS_COLOR_SET, default=default)


def _ml_arnold_look():
    """mossGreen / mossStrand / mossSpore aiStandardSurface networks: world
    space hue patches and mottle, dry pale patches, drier at the patches'
    edges and darker down in the bed (the shading data), per-cushion and
    per-shoot hue shifts, subsurface and sheen. Returns {material: shader}."""
    data = _ml_data("mossData_UDC")
    hue = _ml_noise("mossHue_NOI", 0.3, (0.12, 0.25, 0.03), (0.32, 0.48, 0.07))
    mott = _ml_noise("mossMottle_NOI", 0.035, (0, 0, 0), (1, 1, 1))
    c = _ml_layer("mossMottle_LAY", hue + ".outColor", (0.05, 0.11, 0.02),
                  _ml_range("mossMottle_RNG", mott + ".outColorR", 0.2, 0.8, 0.0, 0.5) + ".outColorR")
    c = _ml_layer("mossCushion_LAY", c + ".outColor", (0.30, 0.42, 0.06),
                  _ml_range("mossCushion_RNG", data + ".outColorR", 0.55, 1.0, 0.0, 0.45) + ".outColorR")
    dry = _ml_noise("mossDry_NOI", 0.4, (0, 0, 0), (1, 1, 1), octaves=2)
    c = _ml_layer("mossDry_LAY", c + ".outColor", (0.36, 0.38, 0.17),
                  _ml_range("mossDry_RNG", dry + ".outColorR", 0.62, 0.8, 0.0, 0.6) + ".outColorR")
    c = _ml_layer("mossEdge_LAY", c + ".outColor", (0.34, 0.36, 0.14),
                  _ml_range("mossEdge_RNG", data + ".outColorB", 0.0, 0.6, 0.55, 0.0) + ".outColorR")
    deep = _ml_node("aiMultiply", "mossDeep_MUL")
    cmds.connectAttr(c + ".outColor", deep + ".input1", force=True)
    cmds.connectAttr(_ml_range("mossDeep_RNG", data + ".outColorG", 0.0, 1.0, 0.45, 1.0) + ".outColor",
                     deep + ".input2", force=True)
    bed = _ml_node("aiStandardSurface", "mossGreen_MAT", shader=True, base=0.9, specular=0.25,
                   specularRoughness=0.55, subsurface=0.35, subsurfaceScale=0.008 / scene_m_per_unit(),
                   subsurfaceRadius=(0.5, 0.9, 0.2), sheen=0.45, sheenRoughness=0.35, sheenColor=(0.55, 0.65, 0.3))
    cmds.connectAttr(deep + ".outColor", bed + ".baseColor", force=True)
    cmds.connectAttr(c + ".outColor", bed + ".subsurfaceColor", force=True)
    fib = _ml_noise("mossFibre_NOI", 0.007, (0, 0, 0), (1, 1, 1), distortion=2.0)
    bump = _ml_node("aiBump2d", "mossFibre_BMP", bumpHeight=0.06)
    cmds.connectAttr(fib + ".outColorR", bump + ".bumpMap", force=True)
    cmds.connectAttr(bump + ".outValue", bed + ".normalCamera", force=True)
    # shoots: thin translucent leaves; a hue shift per shoot (instances: Arnold's per-object random)
    obj = _ml_node("aiUtility", "mossShootId_UTL", shadeMode=2)
    modes = (cmds.attributeQuery("colorMode", node=obj, listEnum=True) or [""])[0].split(":")
    if "obj" in modes:
        cmds.setAttr(obj + ".colorMode", modes.index("obj"))
    sdata = _ml_data("mossShootData_UDC")
    cmds.connectAttr(obj + ".outColor", sdata + ".default", force=True)
    sh = _ml_noise("mossShootHue_NOI", 0.3, (0.26, 0.42, 0.06), (0.50, 0.62, 0.12))
    sc = _ml_layer("mossShoot_LAY", sh + ".outColor", (0.16, 0.30, 0.04),
                   _ml_range("mossShoot_RNG", sdata + ".outColorR", 0.0, 1.0, 0.0, 0.6) + ".outColorR")
    st = _ml_node("aiStandardSurface", "mossStrand_MAT", shader=True, base=0.9, specular=0.3, specularRoughness=0.45,
                  thinWalled=1, subsurface=0.45, sheen=0.3, sheenRoughness=0.3)
    cmds.connectAttr(sc + ".outColor", st + ".baseColor", force=True)
    cmds.connectAttr(sc + ".outColor", st + ".subsurfaceColor", force=True)
    cap = _ml_node("aiStandardSurface", "mossSpore_MAT", shader=True, base=0.9, specular=0.4, specularRoughness=0.4,
                   thinWalled=1, subsurface=0.3, baseColor=(0.35, 0.12, 0.04), subsurfaceColor=(0.5, 0.18, 0.05))
    return {"mossGreen": bed, "mossStrand": st, "mossSpore": cap}


def _ml_disp_look(shader):
    """MOSS_DISP_SG: the bed's shader (mossGreen_MAT) with a displacement:
    world-space cushions with fibres over them, fading to nothing at the
    patches' edges (mossData B), so a Mat's rim stays down where it rolls
    under; how high is each bed's own aiDispHeight (Displacement)."""
    data = _ml_data("mossDispData_UDC")
    cush = _ml_noise("mossDispCushion_NOI", 0.025, (0, 0, 0), (1, 1, 1), octaves=2)
    fib = _ml_noise("mossDispFibre_NOI", 0.005, (0, 0, 0), (1, 1, 1), octaves=2, distortion=1.5)
    mix = _ml_node("aiLayerRgba", "mossDisp_LAY", enable1=1, enable2=1, mix2=0.35)
    cmds.connectAttr(cush + ".outColor", mix + ".input1", force=True)
    cmds.connectAttr(fib + ".outColor", mix + ".input2", force=True)
    edge = _ml_range("mossDispEdge_RNG", data + ".outColorB", 0.0, 0.25)
    mul = _ml_node("aiMultiply", "mossDispEdge_MUL")
    cmds.connectAttr(mix + ".outColor", mul + ".input1", force=True)
    cmds.connectAttr(edge + ".outColor", mul + ".input2", force=True)
    dsp = cmds.shadingNode("displacementShader", asShader=True, name="mossDisp_DSP", skipSelect=True)
    cmds.connectAttr(mul + ".outColorR", dsp + ".displacement", force=True)
    sg = cmds.sets(renderable=True, noSurfaceShader=True, empty=True, name=MOSS_DISP_SG)
    cmds.connectAttr(shader + ".outColor", sg + ".surfaceShader", force=True)
    cmds.connectAttr(dsp + ".displacement", sg + ".displacementShader", force=True)
    return sg


def _ml_plain_look():
    """Without Arnold: flat standardSurface colours."""
    out = {}
    for name, rgb, extra in (("mossGreen", (0.16, 0.28, 0.04), {"subsurface": 0.3, "sheen": 0.4}),
                             ("mossStrand", (0.32, 0.48, 0.08), {"thinWalled": 1, "subsurface": 0.4}),
                             ("mossSpore", (0.35, 0.12, 0.04), {"thinWalled": 1})):
        out[name] = _ml_node("standardSurface", name + "_MAT", shader=True, baseColor=rgb, specularRoughness=0.5,
                             **extra)
    return out


def sc_moss_look(roots):
    """A starter moss look (one Ctrl+Z): mossGreen_MAT / mossStrand_MAT /
    mossSpore_MAT (aiStandardSurface networks with MtoA loaded, plain
    standardSurface without), made once per scene and assigned to the
    Moss layers' bed, strands, instanced shoots and capsules in roots.
    A Mat rendered as _GED gets MOSS_DISP_SG (the bed shader with a
    displacement) on its bed. Returns {"materials": [...], "parts": n,
    "arnold": bool}."""
    arnold = bool(cmds.pluginInfo("mtoa", query=True, loaded=True))
    with UndoChunk("Moss Look"):
        mats = {}
        for name in MOSS_LOOK_PARTS.values():
            sg = name + "_SG"
            if cmds.objExists(sg) and cmds.nodeType(sg) == "shadingEngine":
                mats[name] = sg
        if len(mats) < len(MOSS_LOOK_PARTS):
            made = _ml_arnold_look() if arnold else _ml_plain_look()
            for name, shader in made.items():
                if name in mats:
                    continue
                sg = cmds.sets(renderable=True, noSurfaceShader=True, empty=True, name=name + "_SG")
                cmds.connectAttr(shader + ".outColor", sg + ".surfaceShader", force=True)
                mats[name] = sg
        disp = None  # a Mat rendered as _GED: the bed shader with its displacement
        if arnold:
            if cmds.objExists(MOSS_DISP_SG) and cmds.nodeType(MOSS_DISP_SG) == "shadingEngine":
                disp = MOSS_DISP_SG
            elif any(sc_type(layer.get("type")) == "Moss" and _sc_bed_render(sc_settings(layer))[0] == "GED"
                     for root in roots for layer in sc_data(root).get("layers", [])):
                green = cmds.listConnections(mats["mossGreen"] + ".surfaceShader", source=True,
                                             destination=False) or []
                if green:
                    disp = _ml_disp_look(green[0])
        n = 0
        for root in roots:
            data = sc_data(root)
            parts, shoots = sc_parts(root), sc_shoots(root)
            for layer in data.get("layers", []):
                if sc_type(layer.get("type")) != "Moss":
                    continue
                ged = disp is not None and _sc_bed_render(sc_settings(layer))[0] == "GED"
                for part, mat in MOSS_LOOK_PARTS.items():
                    node = parts.get(layer["id"] + "/" + part)
                    if node:
                        cmds.sets(node, edit=True, forceElement=disp if (ged and part == "moss") else mats[mat])
                        shape = _log_shape(node)
                        if arnold and shape and cmds.attributeQuery("aiExportColors", node=shape, exists=True):
                            cmds.setAttr(shape + ".aiExportColors", True)  # the shading data to Arnold
                        n += 1
                node = shoots.get(layer["id"] + "/shoots")
                protos = _sc_shoot_nodes(node)[2] if node else []
                if protos:
                    cmds.sets(protos, edit=True, forceElement=mats["mossStrand"])
                    n += 1
    return {"materials": sorted(mats) + ([disp[:-3]] if disp else []), "parts": n, "arnold": arnold}


MOSS_DISP_SG = "mossGreenDisp_SG"  # Moss Look's bed shader with its displacement (Mat beds rendered as _GED)


def _sc_bed_render(s):
    """(suffix, Arnold subdivision steps, displacement height in scene
    units or None) for a Moss layer's bed: Carpet _GES (1 step) from Normal
    up, else _GEP; Mat by its Render as."""
    if s.get("style") == MOSS_STYLES[2]:
        want = s.get("render_as") if s.get("render_as") in MOSS_RENDER_AS else "GED"
        disp = max(0.0, float(s.get("disp_height", 0.01))) / scene_m_per_unit() if want == "GED" else None
        return want, MOSS_MAT_ITERS[want], disp
    return ("GES", 1, None) if s.get("detail") in MOSS_BED_SMOOTH else ("GEP", 0, None)


def _sc_bed_suffix(node, s):
    """A moss bed named for how it renders (_sc_bed_render): _GES / _GED
    (subdivided at render time: its cells are coarse) or _GEP; with MtoA
    loaded, Arnold's subdivision (Catmull-Clark) set to match when the
    suffix changes (a step count set by hand stays), and a _GED's
    displacement height and bounds padding kept at Displacement. Moss
    Look's bed shaders follow it (_sc_bed_look). Returns the node."""
    want, steps, disp = _sc_bed_render(s)
    name = short_name(node)
    stem, _, suf = name.rpartition("_")
    renamed = False
    if stem and suf in MOSS_RENDER_AS and suf != want:
        node = long_name(cmds.rename(node, stem + "_" + want))
        renamed = True
    shape = _log_shape(node)
    if shape and cmds.attributeQuery("aiSubdivType", node=shape, exists=True):
        if cmds.getAttr(shape + ".aiSubdivType") != (1 if steps else 0) or (
                renamed and s.get("style") == MOSS_STYLES[2]):
            cmds.setAttr(shape + ".aiSubdivType", 1 if steps else 0)
            cmds.setAttr(shape + ".aiSubdivIterations", steps)
        if disp is not None:
            for attr, v in (("aiDispHeight", disp), ("aiDispPadding", disp)):
                if cmds.attributeQuery(attr, node=shape, exists=True) and \
                        abs(cmds.getAttr(shape + "." + attr) - v) > 1e-9:
                    cmds.setAttr(shape + "." + attr, v)
            if renamed:
                for attr, v in (("aiDispZeroValue", 0.0), ("aiDispAutobump", True)):
                    if cmds.attributeQuery(attr, node=shape, exists=True):
                        cmds.setAttr(shape + "." + attr, v)
    if shape:
        _sc_bed_look(shape, want == "GED")
    return node


def _sc_bed_look(shape, ged):
    """A bed with Moss Look's shader: the one with the displacement on a
    _GED, the plain one otherwise (when both are in the scene)."""
    sgs = cmds.listConnections(shape, type="shadingEngine") or []
    have, want = ("mossGreen_SG", MOSS_DISP_SG) if ged else (MOSS_DISP_SG, "mossGreen_SG")
    if have in sgs and cmds.objExists(want) and cmds.nodeType(want) == "shadingEngine":
        cmds.sets(shape, edit=True, forceElement=want)


def _sc_write_layer_shoots(root, layer, placed, shoots, parts):
    """A Moss layer's instanced shoots into its shoots node (made the first
    time, in the control group; deleted when there are none, refilled only
    when they changed). Returns the faces the instances make."""
    key = layer["id"] + "/shoots"
    mesh = placed.get(key)
    node = shoots.get(key)
    if not mesh:
        if node:
            cmds.delete(node)
            _SC_WROTE.pop((root, key), None)
        return 0
    if node is None:
        node = shoots[key] = _sc_make_shoots(root, layer, "mossStrand")
    sig = _sc_shoots_sig(mesh)
    if _SC_WROTE.get((root, key)) != sig or not _sc_shoot_nodes(node)[1]:
        _sc_fill_shoots(node, mesh, sg=_sc_sg(parts.get(layer["id"] + "/strands")))
        _SC_WROTE[(root, key)] = sig
    else:
        _sc_shoots_order(node)  # (one written before the fix)
    if not cmds.getAttr(node + ".visibility"):
        cmds.setAttr(node + ".visibility", True)
    per = [f for _, f, _ in mesh[6]]
    return sum(per[i] for i in mesh[7]["index"])


def sc_regrow(root, only=None, readback=True, budget=True, draft=None):
    """Grow a group again from its JSON (outside the undo queue), in the
    Working window (Esc / Cancel stops it). budget: a build that would take
    a minute or more isn't started (live edits: the user changed one
    setting on a big scatter and Maya seemed frozen). Stopped, nothing
    changes and it pauses (the edits are kept: Play grows them). Returns
    its report ("held" and "stopped" when stopped)."""
    sc_fix_box(root)
    _sc_note(root)
    data = sc_data(root)
    _MI_BUDGET["on"] = bool(budget)
    try:
        with Progress("Scatter: growing %s" % short_name(root), [("grow", 1)]) as pr:
            pr.stage("grow", 1, "Growing")
            with NoUndo(), GcPaused():
                placed, report, meshes = sc_build(root, data, only=only, readback=readback, draft=draft)
    except (Cancelled, ScatterTooBig) as exc:
        return _sc_stopped(root, data, exc)
    finally:
        _MI_BUDGET["on"] = False
    layers = report.pop("layers", {})
    skey = report.pop("skey", None)
    with NoUndo():
        report["faces"] = _sc_write(root, data, placed, meshes)
        stamp = "%d" % random.randint(1, 1 << 30)
        cmds.setAttr(root + "." + SC_STAMP, stamp, type="string")
        now = cmds.getAttr(root + "." + SC_ATTR)
        _sc_set_text(root, SC_GROWN, now)
        _sc_set_text(root, SC_COUNTS, json.dumps(layers, sort_keys=True))
        if skey is not None:
            _sc_set_text(root, SC_SURF, json.dumps(skey))
    _SC_LAST[root] = (now, stamp)
    if skey is not None:
        _SC_SURF[root] = json.loads(json.dumps(skey))
    report["root"] = root
    return report


def _sc_stopped(root, data, exc):
    """A build stopped (Cancel, or too big for a live edit): pause, keep the
    edits, fit the box round what's there. Returns the held report."""
    sc_pause()
    with NoUndo():
        _sc_fit_box(root, sc_box(root), sc_surfaces(data))
    rep = _sc_held(root)
    rep["stopped"] = ("it would take a minute or more to grow (%s)" % exc) if isinstance(exc, ScatterTooBig) \
        else "cancelled"
    return rep


def sc_sync():
    """Regrow every group whose JSON or stamp no longer matches what was
    built (an undo / redo of a structural change, a redo of a new group).
    While paused nothing grows (Play grows it). Returns the groups regrown."""
    done = []
    hold = _SC_HOLD
    _sc_drop_orphan_boxes()
    for root in sc_groups():
        now = (cmds.getAttr(root + "." + SC_ATTR), cmds.getAttr(root + "." + SC_STAMP) or "")
        last = _SC_LAST.get(root)
        if last is None and now[1]:  # opened with the scene: as last grown
            _sc_note(root)
            continue
        if hold["on"]:
            if hold["seen"].get(root) != now[0]:  # the undo / redo changed it: Ctrl+Z's state now
                hold["base"][root] = hold["seen"][root] = now[0]
            continue
        if last != now:
            sc_regrow(root)
            done.append(root)
    return done


def sc_paused():
    return _SC_HOLD["on"]


def sc_pause():
    """Pause live updates: edits (settings, layers, areas, surfaces) are
    saved to the groups but nothing grows until sc_play."""
    if not _SC_HOLD["on"]:
        now = dict((r, cmds.getAttr(r + "." + SC_ATTR)) for r in sc_groups())
        _SC_HOLD.update(on=True, base=now, seen=dict(now), force=set())


def _sc_held(root, before=None):
    """After an edit saved while paused: note what was written (before: the
    JSON before a live edit, for Ctrl+Z after Play). Returns its report."""
    now = cmds.getAttr(root + "." + SC_ATTR)
    if before is None:  # an undoable edit: Ctrl+Z after Play goes back to here
        _SC_HOLD["base"][root] = now
    else:
        _SC_HOLD["base"].setdefault(root, before)
    _SC_HOLD["seen"][root] = now
    return {"root": root, "held": True, "faces": 0, "surfaces": len(sc_surfaces(sc_data(root)))}


def _sc_commit(roots, label):
    """While paused: each group's live edits since its last undoable state
    go on the undo queue, all as one Ctrl+Z (label) that takes them back."""
    moved = []
    for root in roots:
        now = cmds.getAttr(root + "." + SC_ATTR)
        old = _SC_HOLD["base"].get(root)
        if old is not None and old != now:
            moved.append((root, old, now))
            _SC_HOLD["base"][root] = now
    if moved:
        with UndoChunk(label):
            for root, old, now in moved:
                with NoUndo():
                    cmds.setAttr(root + "." + SC_ATTR, old, type="string")
                cmds.setAttr(root + "." + SC_ATTR, now, type="string")


def sc_drafting():
    return _SC_DRAFT["on"]


def sc_set_draft(on):
    """Draft on / off: moss layers that grow from now on grow their quick
    look (off: in full). What's grown stays as it is (sc_full_detail)."""
    _SC_DRAFT["on"] = bool(on)


def sc_drafted(root):
    """Ids of a group's on layers whose parts show a draft (as last grown)."""
    if not is_scatter(root) or not cmds.attributeQuery(SC_COUNTS, node=root, exists=True):
        return []
    try:
        counts = json.loads(cmds.getAttr(root + "." + SC_COUNTS) or "{}")
    except ValueError:
        return []
    return [l["id"] for l in sc_data(root).get("layers", [])
            if l.get("on", True) and (counts.get(l["id"]) or {}).get("draft")]


def sc_full_detail(roots):
    """Grow the groups' draft layers properly (outside the undo queue, like
    any regrow; while paused: at Play). Returns the reports of the groups
    grown (the last one "stopped" when cancelled)."""
    if _SC_HOLD["on"]:
        _SC_DRAFT["later"].update(r for r in roots if sc_drafted(r))
        return []
    reps = []
    for root in roots:
        ids = sc_drafted(root)
        if not ids:
            continue
        rep = sc_regrow(root, only=set(ids), budget=False, draft=False)
        reps.append(rep)
        if rep.get("stopped"):
            break
    return reps


def sc_regrow_later(roots):
    """Regrow pressed while paused: the groups grow at Play."""
    _SC_HOLD["force"].update(roots)


def sc_pending(root):
    """What a group's grown parts lag behind (edits saved while paused):
    (ids of layers added or changed since it last grew, whether the group
    itself changed: surfaces, UDIM, layer order, a layer removed, Regrow
    pressed), or None when it's up to date."""
    if not is_scatter(root):
        return None
    _sc_note(root)
    forced = root in _SC_HOLD["force"]
    last = _SC_LAST.get(root)
    now = cmds.getAttr(root + "." + SC_ATTR) or "{}"
    if last is None or last[0] == now:
        return (set(), True) if forced else None
    try:
        old, new = json.loads(last[0] or "{}"), json.loads(now)
    except ValueError:
        return set(), True
    was = dict((l.get("id"), l) for l in old.get("layers", []))
    changed = set(l.get("id") for l in new.get("layers", []) if was.get(l.get("id")) != l)

    def rest(d):
        return dict((k, v) for k, v in d.items() if k not in ("layers", "next", "version"))

    group = forced or rest(old) != rest(new) or [i for i in was if i not in changed] != [
        l.get("id") for l in new.get("layers", []) if l.get("id") not in changed]
    return (changed, group) if changed or group else None


def sc_play():
    """Play: grow every group whose parts lag behind its JSON, each changed
    layer built once (unchanged layers come from the cache), and put the
    live edits made while paused on the undo queue as one Ctrl+Z (it takes
    them back and regrows). Returns the reports of the groups grown."""
    roots = sc_groups()
    _sc_commit(roots, "Scatter play")
    hold = dict(_SC_HOLD)
    _SC_HOLD.update(on=False, base={}, seen={}, force=set())
    reps = []
    for k, root in enumerate(roots):
        last = _SC_LAST.get(root)
        now = (cmds.getAttr(root + "." + SC_ATTR), cmds.getAttr(root + "." + SC_STAMP) or "")
        if root in hold["force"] or (last is not None and last != now):
            rep = sc_regrow(root, readback=root not in hold["force"], budget=False)
            reps.append(rep)
            if rep.get("stopped"):  # cancelled: paused again, the rest wait too
                _SC_HOLD["force"].update(r for r in roots[k + 1:] if r in hold["force"])
                break
    else:
        later, _SC_DRAFT["later"] = _SC_DRAFT["later"], set()
        reps.extend(sc_full_detail([r for r in roots if r in later]))
    return reps


def create_scatter_group(surfaces, layer_type="Moss", settings=None, points=None, faces=None, select=True,
                         drawing=None):
    """A new scatter group on meshes / groups with one layer (one Ctrl+Z):
    scatteredObjects####_GRP, its box, and the layer's parts. points /
    faces: the layer's area; drawing: strokes it goes along (their meshes
    are surfaces too). Returns the report (with "root")."""
    surfaces = list(surfaces or ()) + sc_drawing_meshes(drawing)
    nodes = []
    for s in surfaces or ():
        if s and cmds.objExists(s) and not sc_owner(s)[0] and not _mi_part_of(s):
            s = long_name(s)
            if s not in nodes:
                nodes.append(s)
    if not nodes:
        raise ValueError("select the meshes or groups to scatter onto")
    data = {"version": SC_VERSION, "surfaces": [cmds.ls(n, uuid=True)[0] for n in nodes], "udim": 1001, "next": 1,
            "layers": []}
    layer = _sc_new_layer(data, layer_type, settings)
    meshes = sc_surfaces(data)
    layer["seeds"] = _mi_store_seeds(list(points or [])[:MI_MAX_SEEDS], meshes)
    layer["faces"] = _mi_store_faces(faces) if layer["type"] != "Ivy" else {}
    layer["draw"] = sc_store_drawing(drawing)
    data["layers"].append(layer)
    with UndoChunk("New scatter group"):
        root = _sc_new_root(data, select)
    return sc_regrow(root)


def _sc_new_root(data, select=True):
    """A scatteredObjects####_GRP holding data, with its box beside it
    (inside the caller's Ctrl+Z). Returns the group."""
    num = _th_free_number(SC_STEM + "%04d_GRP")
    root = long_name(cmds.group(empty=True, world=True, name="%s%04d_GRP" % (SC_STEM, num)))
    cmds.addAttr(root, longName=SC_ATTR, dataType="string")
    cmds.addAttr(root, longName=SC_STAMP, dataType="string")
    _sc_set(root, data)
    # move / rotate / scale stay free: dragged under a moved group, Maya keeps it in place (parts are written
    # through the group's matrix, so they sit on the surfaces wherever it is)
    box = _sc_make_box(root)  # beside the group, so it can go into a publish group without its box
    cmds.parent(box, _sc_make_control(root, box))  # in its control group (instanced shoots go there too)
    if select:
        cmds.select(root, replace=True)
    return root


def sc_new_group_from(root, layers=False, select=True):
    """A new scatter group on exactly what root scatters onto - its
    surfaces, what's left out of them, its Start UDIM - (one Ctrl+Z):
    blank (no layers: add some), or with layers=True a copy of every
    layer (each a new seed, so it isn't the same scatter twice). Its box
    goes round the surfaces. Returns the report
    (with "root")."""
    data = json.loads(json.dumps(sc_data(root)))  # all of it, its own copy
    if layers:
        for layer in data.get("layers") or []:
            s = layer.setdefault("s", {})
            s["seed"] = int(s.get("seed", 1)) + 1
    else:
        data["layers"], data["next"] = [], 1
    if not sc_surfaces(data):
        raise ValueError("%s has no surfaces left to scatter onto" % short_name(root))
    with UndoChunk("Duplicate scatter group" if layers else "New scatter group from %s" % short_name(root)):
        new = _sc_new_root(data, select)
    return sc_regrow(new)


def _sc_change(root, label, fn):
    """A structural change to a group's JSON (one Ctrl+Z; fn(data) edits it,
    may return parts to delete), then the regrow."""
    _sc_note(root)
    if _SC_HOLD["on"]:  # paused live edits before it: their own Ctrl+Z
        _sc_commit([root], "Scatter edits")
    data = sc_data(root)
    gone = fn(data) or []
    with UndoChunk(label):
        _sc_set(root, data)
        for node in gone:
            if cmds.objExists(node):
                cmds.delete(node)
    if _SC_HOLD["on"]:
        return _sc_held(root)
    return sc_regrow(root)


SC_ADD_TOP_VAR = "unlokScatterAddTop"  # optionVar: 0 when Add Layer puts new layers at the bottom of the list


def sc_add_layer(root, layer_type, settings=None, points=None, faces=None, copy_of=None, drawing=None,
                 draw_of=None, top=False):
    """Add a layer (one Ctrl+Z): a type's defaults (or settings), or a copy
    of another layer (copy_of: its id; a new seed); drawing: strokes it goes
    along (meshes they're on that the group doesn't scatter onto yet are
    added); draw_of: another layer's id, whose strokes it goes along too
    (Add Layer with a drawn layer picked: the user, 2026-11-12, "is that
    other layer on the same strokes?"); top: first in the list (on top of
    the others, On layers below), else last. Returns (report, id)."""
    made = []

    def edit(data):
        src = sc_layer(data, copy_of) if copy_of else None
        if src is not None:
            layer = _sc_new_layer(data, src["type"], dict(src.get("s") or {}),
                                  name=src.get("name", src["type"]) + " copy")
            layer["s"]["seed"] = int(layer["s"].get("seed", 1)) + 1
            layer["seeds"], layer["faces"] = list(src.get("seeds") or []), dict(src.get("faces") or {})
            layer["draw"] = json.loads(json.dumps(src.get("draw") or {}))
            if src.get("paint"):
                layer["paint"] = json.loads(json.dumps(src["paint"]))
        else:
            layer = _sc_new_layer(data, layer_type, settings)
            if points:
                layer["seeds"] = _mi_store_seeds(list(points)[:MI_MAX_SEEDS], sc_surfaces(data))
            if faces and layer["type"] != "Ivy":
                layer["faces"] = _mi_store_faces(faces)
            if drawing:
                _sc_add_drawn_surfaces(data, drawing)
                layer["draw"] = sc_store_drawing(drawing)
            elif draw_of:
                src = sc_layer(data, draw_of)
                if src is not None and src.get("draw"):
                    layer["draw"] = json.loads(json.dumps(src["draw"]))
        if top:
            data["layers"].insert(0, layer)
        else:
            data["layers"].append(layer)
        made.append(layer["id"])
    rep = _sc_change(root, "Add scatter layer", edit)
    return rep, made[0]


def sc_remove_layer(root, lid):
    """Remove a layer and its parts (one Ctrl+Z)."""
    def edit(data):
        data["layers"] = [l for l in data["layers"] if l.get("id") != lid]
        return [n for k, n in list(sc_parts(root).items()) + list(sc_shoots(root).items()) if k.split("/")[0] == lid]
    return _sc_change(root, "Remove scatter layer", edit)


def _sc_add_drawn_surfaces(data, drawing):
    """Meshes a drawing is on that the group doesn't scatter onto yet join
    its surfaces (drawing on a mesh left out of a group puts it back)."""
    have = set(sc_surfaces(data))
    for node in sc_drawing_meshes(drawing):
        if node not in have and not sc_owner(node)[0] and not _mi_part_of(node):
            _sc_include(data, node)


def sc_set_layer(root, lid, on=None, name=None, area=None, drawing=None, add_drawing=None):
    """Turn a layer on / off, rename it, set its area (points, faces) or its
    drawing (strokes; [] clears it), or add strokes to its drawing
    (add_drawing) (one Ctrl+Z)."""
    def edit(data):
        layer = sc_layer(data, lid)
        if layer is None:
            return
        if on is not None:
            layer["on"] = bool(on)
        if name:
            layer["name"] = name
        if area is not None:
            points, faces = area
            meshes = sc_surfaces(data)
            layer["seeds"] = _mi_store_seeds(list(points or [])[:MI_MAX_SEEDS], meshes)
            layer["faces"] = _mi_store_faces(faces) if layer["type"] != "Ivy" else {}
        if drawing is not None:
            if drawing:
                _sc_add_drawn_surfaces(data, drawing)
            layer["draw"] = sc_store_drawing(drawing)
        if add_drawing:
            _sc_add_drawn_surfaces(data, add_drawing)
            layer["draw"] = _sc_draw_join(layer.get("draw") or {}, sc_store_drawing(add_drawing))
    return _sc_change(root, "Scatter layer", edit)


def sc_delete_strokes(root, lid, indices):
    """Take strokes (indices into the layer's drawing) out of it, then only
    that layer grows again (one Ctrl+Z; while paused: at Play). The user,
    2026-11-05: "I've realized one of the ones I painted I don't want
    anymore. I've already scattered, so how can I just remove that?"."""
    drop = set(int(i) for i in indices or ())

    def edit(data):
        layer = sc_layer(data, lid)
        if layer is None or not drop:
            return
        rows = (layer.get("draw") or {}).get("k") or []
        layer["draw"] = _sc_draw_keep(layer.get("draw") or {}, [i for i in range(len(rows)) if i not in drop])
    return _sc_change(root, "Delete scatter strokes", edit)


def sc_set_paint(root, lid, paint, label="Scatter paint"):
    """Set a layer's influence paint (an ScPaint or its dump; empty clears
    it) (one Ctrl+Z: a brush stroke, a Flood, a Clear), then the regrow of
    that layer (while paused: at Play)."""
    if isinstance(paint, ScPaint):
        paint = paint.dump()

    def edit(data):
        layer = sc_layer(data, lid)
        if layer is None:
            return
        if paint:
            layer["paint"] = paint
        else:
            layer.pop("paint", None)
    return _sc_change(root, label, edit)


def sc_paint(root, lid):
    """A layer's influence paint to edit (ScPaint)."""
    layer = sc_layer(sc_data(root), lid) if is_scatter(root) else None
    return ScPaint((layer or {}).get("paint"))


def sc_move_layer(root, lid, step):
    """Move a layer up (-1) or down (+1) the list (UDIM order) (one Ctrl+Z)."""
    def edit(data):
        ls = data["layers"]
        i = next((k for k, l in enumerate(ls) if l.get("id") == lid), None)
        if i is not None and 0 <= i + step < len(ls):
            ls[i], ls[i + step] = ls[i + step], ls[i]
    return _sc_change(root, "Move scatter layer", edit)


def sc_set_surfaces(root, add=(), remove=()):
    """Add / remove meshes or groups it scatters onto (one Ctrl+Z).
    Removing a mesh (or a group) inside a surface group leaves just that
    out of the group (the user: "add a group, but then click individual
    things inside to remove ... they'll override just for that one
    object"); adding it again puts it back."""
    def edit(data):
        for n in remove or ():  # first, so swapping a group for meshes inside it works
            if n and cmds.objExists(n):
                _sc_exclude(data, long_name(n))
        for n in add or ():
            if n and cmds.objExists(n) and not sc_owner(n)[0] and not _mi_part_of(n):
                _sc_include(data, long_name(n))
    return _sc_change(root, "Scatter surfaces", edit)


def sc_update(root, lid=None, change=None, group_change=None, draft=None, layer_change=None):
    """Live edit (out of the undo queue, like the other tools' sliders): a
    layer's settings (change), keys on the layer itself (layer_change: udim,
    its own Start UDIM, 0 / None = with the group) or the group's
    (group_change: udim), then the regrow of that layer (while paused:
    saved, grown at Play; draft: as sc_regrow's). Returns the report."""
    _sc_note(root)
    before = cmds.getAttr(root + "." + SC_ATTR) if _SC_HOLD["on"] else None
    data = sc_data(root)
    if lid and change:
        layer = sc_layer(data, lid)
        if layer is not None:
            layer.setdefault("s", {}).update(change)
    if lid and layer_change:
        layer = sc_layer(data, lid)
        if layer is not None:
            for k, v in layer_change.items():
                if v:
                    layer[k] = v
                else:
                    layer.pop(k, None)
    if group_change:
        data.update(group_change)
    with NoUndo():
        _sc_set(root, data)
    if _SC_HOLD["on"]:
        return _sc_held(root, before)
    return sc_regrow(root, draft=draft)


def sc_surface_names(data):
    """[(uuid, long name or None, "mesh" / "group" / "left out")] of a
    group's surfaces, each group followed by what's left out of it."""
    out = []
    left = [(u, (cmds.ls(u, long=True) or [None])[0]) for u in data.get("exclude") or []]
    for uid in data.get("surfaces") or []:
        found = cmds.ls(uid, long=True) or []
        node = found[0] if found else None
        out.append((uid, node, "mesh" if node and _log_shape(node) else "group"))
        if node and not _log_shape(node):
            out.extend((u, n, "left out") for u, n in left if n and n.startswith(node + "|"))
    return out


# --------------------------------------------------------------- blockers
# Like the Roof tool's: boxes (or any meshes / groups) where nothing in the group grows, every layer. A mesh
# keeps its own box through its transform (rotate and scale it), a group its world bounding box. Stored on the
# group's JSON as "blockers": [uuid]; moving one grows the group again at the next regrow (its box is in the
# surface key).
def sc_blockers(data):
    """The group's blockers that still exist (long names)."""
    out = []
    for uid in data.get("blockers") or []:
        found = cmds.ls(uid, long=True)
        if found and found[0] not in out:
            out.append(found[0])
    return out


def _sc_blocker_boxes(data):
    """World boxes {"id", "c", "u", "h"} of the group's blockers as they are
    now (rounded, so a reopened scene keys the same; gone or flat ones left
    out)."""
    boxes = []
    for node in sc_blockers(data):
        b = _th_blocker_box(node)
        if b:
            boxes.append({"id": b["id"], "c": [round(v, 6) for v in b["c"]],
                          "u": [[round(v, 6) for v in u] for u in b["u"]], "h": [round(v, 6) for v in b["h"]]})
    return boxes


def _sc_blocker_keys(blocks):
    """Blocker boxes as entries of a group's surface key (_sc_same_surf compares them like meshes)."""
    return tuple(("blocker:" + b["id"], 0, 0, tuple(b["c"]) + tuple(v for u in b["u"] for v in u), tuple(b["h"]))
                 for b in blocks)


def sc_blockers_moved(root):
    """True when a blocker of the group was moved, rotated or scaled since
    it last grew (the panel regrows it then)."""
    _sc_note(root)
    known = _SC_SURF.get(root)
    if known is None or not is_scatter(root):
        return False
    old = [x for x in known if str(x[0]).startswith("blocker:")]
    now = json.loads(json.dumps(_sc_blocker_keys(_sc_blocker_boxes(sc_data(root)))))
    return not _sc_same_surf(old, now)


def sc_set_blockers(root, add=(), remove=(), label="Scatter blockers"):
    """Make nodes blockers of the group (add) or stop them being blockers
    (remove), then regrow (one Ctrl+Z). Its own box and parts never are."""
    def edit(data):
        have = [u for u in data.get("blockers") or [] if cmds.ls(u)]
        own = set(cmds.ls([n for n in [sc_box(root), sc_control(root)] if n], uuid=True) or [])
        for n in add or ():
            if not n or not cmds.objExists(n) or sc_owner(n)[0] == root and not _sc_blocker_of(n):
                continue
            uid = cmds.ls(n, uuid=True)[0]
            if uid not in have and uid not in own:
                have.append(uid)
        gone = set(u for n in remove or () if n and cmds.objExists(n) for u in cmds.ls(n, uuid=True))
        data["blockers"] = [u for u in have if u not in gone]
    return _sc_change(root, label, edit)


def _sc_blocker_of(node):
    """The uuid of the group a blocker box the tool made belongs to, or ""."""
    if node and cmds.objExists(node) and cmds.attributeQuery(SC_BLOCKER_ATTR, node=node, exists=True):
        return cmds.getAttr(node + "." + SC_BLOCKER_ATTR) or ""
    return ""


def sc_create_blocker(root):
    """A blocker box for the group: a red wireframe cube (never renders) in
    the middle of the group's box, a third of its size and as tall, in its
    control group (one Ctrl+Z with linking it). Selected; returns
    (report, node)."""
    ref = sc_box(root)
    bb = cmds.exactWorldBoundingBox(ref) if ref else None
    if not bb:
        meshes = sc_surfaces(sc_data(root))
        if not meshes:
            raise ValueError("%s has nothing to place a blocker by" % short_name(root))
        bb = cmds.exactWorldBoundingBox(meshes)
    size = [max(bb[3 + i] - bb[i], 1e-3) for i in range(3)]
    s = [size[0] / 3.0, max(size[1], 0.5 / scene_m_per_unit()), size[2] / 3.0]
    with UndoChunk("Scatter blocker"):
        num = _th_free_number("scatterBlocker%04d")
        node = long_name(cmds.polyCube(width=1, height=1, depth=1, constructionHistory=False,
                                       name="scatterBlocker%04d" % num)[0])
        shape = _log_shape(node)
        cmds.addAttr(node, longName=SC_BLOCKER_ATTR, dataType="string")
        cmds.setAttr(node + "." + SC_BLOCKER_ATTR, cmds.ls(root, uuid=True)[0], type="string")
        for attr in ("castsShadows", "receiveShadows", "primaryVisibility", "visibleInReflections",
                     "visibleInRefractions"):
            if cmds.attributeQuery(attr, node=shape, exists=True):
                cmds.setAttr(shape + "." + attr, False)
        cmds.setAttr(node + ".overrideEnabled", True)
        cmds.setAttr(node + ".overrideShading", False)
        cmds.setAttr(node + ".overrideColor", 13)  # red wireframe: not the group's box
        ctl = sc_control(root)
        if ctl:
            node = long_name(cmds.parent(node, ctl)[0])
        mid = ((bb[0] + bb[3]) * 0.5, bb[1] + s[1] * 0.5 - 0.1 * size[1], (bb[2] + bb[5]) * 0.5)
        cmds.xform(node, worldSpace=True, matrix=[s[0], 0.0, 0.0, 0.0, 0.0, s[1], 0.0, 0.0, 0.0, 0.0, s[2], 0.0,
                                                   mid[0], mid[1], mid[2], 1.0])
        rep = sc_set_blockers(root, add=[node], label="Scatter blocker")
        if cmds.objExists(node):
            cmds.select(node, replace=True)
    return rep, node


def bake_scatter(roots):
    """Plain meshes (one Ctrl+Z): empty parts and the box go, the settings
    move to a hidden attribute. Edits saved while paused grow first (it
    bakes them), and draft moss grows properly first (a draft is never
    baked). A group whose growing was cancelled isn't baked. Returns the
    groups baked."""
    stopped = set()
    for root in roots:
        if _SC_HOLD["on"] and sc_pending(root):
            if sc_regrow(root, budget=False, draft=False).get("stopped"):
                stopped.add(root)
                continue
            _SC_HOLD["force"].discard(root)
        ids = sc_drafted(root)
        if ids and sc_regrow(root, only=set(ids), budget=False, draft=False).get("stopped"):
            stopped.add(root)
    done = []
    with UndoChunk("Scatter bake"):
        for root in roots:
            if not is_scatter(root) or root in stopped:
                continue
            for key, node in sc_shoots(root).items():  # instanced shoots become real geometry
                if cmds.getAttr(node + ".visibility"):
                    _sc_bake_shoots(root, key.split("/")[0], node)
                cmds.delete(node)
            for node in sc_parts(root).values():
                if not cmds.getAttr(node + ".visibility"):
                    cmds.delete(node)
            box = sc_box(root)
            if box:
                cmds.delete(box)
            mine = cmds.ls(root, uuid=True)[0]  # blocker boxes the tool made for it (yours stay), unless
            used = set(u for r in sc_groups() if r != root for u in sc_data(r).get("blockers") or [])  # shared
            for node in sc_blockers(sc_data(root)):
                if _sc_blocker_of(node) == mine and cmds.ls(node, uuid=True)[0] not in used:
                    cmds.delete(node)
            ctl = sc_control(root)
            if ctl and not [k for k in cmds.listRelatives(ctl, children=True, fullPath=True) or []
                            if not cmds.attributeQuery(SC_SHOOTS, node=k, exists=True)]:
                cmds.delete(ctl)  # (only the tool's things were in it)
            if cmds.attributeQuery(SC_BAKED, node=root, exists=True):
                cmds.deleteAttr(root + "." + SC_BAKED)
            cmds.renameAttr(root + "." + SC_ATTR, SC_BAKED)
            done.append(root)
    return done


def _sc_bake_shoots(root, lid, node):
    """Bake: a layer's instanced shoots as real geometry, in its strands
    mesh (a new mesh with the strands and the shoots, in the strands part's
    place and name, its shading; undoable: the old nodes are deleted, the new
    one made with commands)."""
    shoots = _sc_read_shoots(node)
    if shoots is None:
        return None
    mesh = moss_instances_mesh(shoots)
    old = sc_parts(root).get(lid + "/strands")
    sg = _sc_sg(old) or _sc_sg((_sc_shoot_nodes(node)[2] or [None])[0])
    if old is not None and cmds.getAttr(old + ".visibility"):
        got = _sc_read_part(old)
        if got is not None:
            b = len(got[0])
            mesh = (got[0] + mesh[0], got[1] + mesh[1], got[2] + [c + b for c in mesh[2]], got[3] + mesh[3],
                    got[4] + mesh[4], got[5] + [c + b for c in mesh[5]])
    layer = sc_layer(sc_data(root), lid) or {"id": lid, "tag": ""}
    new = _sc_make_part(root, layer, "strands", "mossStrand")
    shape = _log_shape(new)
    cmds.setAttr(shape + "." + MI_VERTS, _rope_fill(shape, mesh))
    if sg:
        cmds.sets(shape, edit=True, forceElement=sg)
    if old is not None:
        name = short_name(old)
        cmds.delete(old)
        new = long_name(cmds.rename(new, name))
    return new


def _tagged_roots(attrs):
    """Long names of the nodes carrying any of attrs (namespaced too)."""
    pats = ["*." + a for a in attrs] + ["*:*." + a for a in attrs]
    return tuple(set(cmds.ls(pats, objectsOnly=True, long=True) or []))


def _under_any(node, roots):
    """node (a long name) is one of roots or below one."""
    return any(node == r or node.startswith(r + "|") for r in roots)


def sc_selection():
    """{"root", "layer", "surfaces", "points", "faces"} from the selection:
    the scatter group (and layer, from a part) picked, meshes and groups
    that could be scattered onto, picked points and faces."""
    out = {"root": None, "layer": None, "surfaces": [], "points": [], "faces": {}}
    # Groups are found once; a node is only asked about if it's under one (a
    # 200-mesh pick asked every mesh, on every click, with the toolbox open).
    sc_roots = _tagged_roots((SC_ATTR, SC_BAKED, SC_BOX_ATTR, SC_CTL))  # boxes / control groups sit beside groups
    mi_roots = _tagged_roots((MI_SETTINGS, MI_BAKED))
    for node in cmds.ls(selection=True, objectsOnly=True, long=True) or []:
        if _under_any(node, sc_roots):
            root, lid = sc_owner(node)
            if root:
                if out["root"] is None:
                    out["root"], out["layer"] = root, lid
                continue
        if cmds.objectType(node, isAType="shape"):
            node = long_name(cmds.listRelatives(node, parent=True, fullPath=True)[0])
        if (_under_any(node, mi_roots) and _mi_part_of(node)) or not cmds.objectType(node, isAType="transform"):
            continue
        if node not in out["surfaces"]:
            out["surfaces"].append(node)
    out["points"], out["faces"] = mi_moss_picks()
    return out


