SC_DRAW_CTX = "unlokScatterDrawCtx"


class ScatterDrawer(SurfacePathDrawer):
    """Draw on Surfaces (the Scatter panel): drag over any visible mesh (not
    a scatter group's own) to draw a stroke on it; a stroke may run across
    many meshes, a click is a single spot. Strokes stay as orange lines
    (outside the undo queue, never saved) until cleared, so several layers
    can go on one drawing. While drawing, Ctrl+Z / Backspace / Delete takes
    the last stroke back (Maya's undo never sees it), Ctrl+Y / Ctrl+Shift+Z
    puts it back, Enter or Esc stops drawing (the strokes stay)."""

    def __init__(self, on_change=None):
        super(ScatterDrawer, self).__init__(on_stroke=lambda *a: None, get_smoothing=lambda: 0,
                                            exclude_roots=lambda: sc_groups())
        self.on_change = on_change
        self.strokes = []   # [[(world point, mesh shape path), ...], ...]
        self.curves = []    # the line showing each stroke
        self.undone = []    # (stroke, ) taken back, newest last: what Ctrl+Y puts back
        self._filter = None
        self.mode = SC_DRAW_ON[0]  # Draw on
        self.only = []             # Draw on Selected: those mesh shapes

    def _candidate_meshes(self, use_forced=True):
        """Meshes a stroke can land on, by Draw on (the user, 2026-11-05: "if
        I bake a bunch of scattered stuff and then want to draw another
        one, it suddenly starts drawing on top of the scattered stuff ...
        I want to be able to sometimes just draw on the underlying
        surface"): Surfaces, any visible mesh but scatter, live or baked;
        Selected, the meshes picked when drawing started; Everything, any
        visible mesh but a live scatter group's."""
        if self.mode == SC_DRAW_ON[1]:
            out = []
            for node in self.only:
                dag = get_dag_path(node) if cmds.objExists(node) else None
                if dag is not None and dag.isVisible():
                    out.append(dag)
            return out
        out = super(ScatterDrawer, self)._candidate_meshes(use_forced=False)
        if self.mode == SC_DRAW_ON[2]:
            return [d for d in out if not _sc_box_mesh(d)]  # never a group's box (beside its group now)
        baked = tuple(r + "|" for r in sc_groups(baked=True))
        return [d for d in out if not (baked and d.fullPathName().startswith(baked)) and not _sc_scatter_mesh(d)]

    # ---------------------------------------------------------- tool
    def activate(self, surfaces=None, mode=None, only=None):
        self.mode = mode or SC_DRAW_ON[0]
        self.only = list(only or [])
        if cmds.draggerContext(SC_DRAW_CTX, exists=True):
            cmds.deleteUI(SC_DRAW_CTX)
        cmds.draggerContext(SC_DRAW_CTX, pressCommand=self._press, dragCommand=self._drag,
                            releaseCommand=self._release, finalize=self._finalize, space="screen",
                            cursor="crossHair", undoMode="step")
        cmds.setToolTo(SC_DRAW_CTX)
        self._ensure_preview()
        if self._filter is None:
            self._filter = _ThatchPickKeys(self)
            QtWidgets.QApplication.instance().installEventFilter(self._filter)
        self._changed()

    @staticmethod
    def is_active():
        try:
            return cmds.currentCtx() == SC_DRAW_CTX
        except RuntimeError:
            return False

    def deactivate(self):
        self._stop_keys()
        if self.is_active():
            cmds.setToolTo("selectSuperContext")
        self._changed()

    def shutdown(self):
        self.deactivate()
        self.clear()
        try:
            self._delete_preview()
        except Exception:
            pass
        if cmds.draggerContext(SC_DRAW_CTX, exists=True):
            cmds.deleteUI(SC_DRAW_CTX)

    def _stop_keys(self):
        if self._filter is not None:
            try:
                QtWidgets.QApplication.instance().removeEventFilter(self._filter)
            except RuntimeError:
                pass
            self._filter = None

    def _finalize(self):  # the user picked another tool
        try:
            self._stop_keys()
            self._delete_preview()
        except Exception:
            pass
        QtCore.QTimer.singleShot(0, _guarded_call(self._changed))

    def _changed(self):
        if self.on_change is not None:
            self.on_change()

    # ------------------------------------------------------ strokes
    def _press(self):
        try:
            x, y, _ = cmds.draggerContext(SC_DRAW_CTX, q=True, anchorPoint=True)
            self.press_at(x, y, cmds.draggerContext(SC_DRAW_CTX, q=True, modifier=True))
        except Exception:
            traceback.print_exc()

    def _drag(self):
        try:
            x, y, _ = cmds.draggerContext(SC_DRAW_CTX, q=True, dragPoint=True)
            self.drag_at(x, y)
        except Exception:
            traceback.print_exc()

    def press_at(self, x, y, mod="none"):
        """Start a stroke: only meshes count (nothing is drawn on empty space)."""
        self._reset()
        self.anchor = (x, y)
        self._ensure_preview()
        self.straight = mod == "shift"
        self.candidates = self._make_candidates(self._candidate_meshes(use_forced=False))
        self.last_screen = (x, y)
        p = self._cast(x, y)
        if p is not None:
            self.points.append(p)

    def release(self):
        try:
            if self.straight and self.last_drag is not None and self.anchor is not None:
                self.points = self._line_points(self.last_drag[0], self.last_drag[1], 6.0)
            self._set_preview_visible(False)
            stroke = []
            for p, mesh in self.points:
                if mesh is not None and (not stroke or _rl_len(_rl_sub((p.x, p.y, p.z), stroke[-1][0])) > 1e-4):
                    stroke.append(((p.x, p.y, p.z), mesh))
            if stroke:
                self.strokes.append(stroke)
                self.curves.append(self._show(stroke))
                self.undone = []
                self._changed()
        finally:
            self.points = []
            self.anchor = None

    def add_stroke(self, stroke):
        """A stroke from a script: [(world point, mesh), ...]."""
        self.strokes.append(list(stroke))
        self.curves.append(self._show(stroke))
        self.undone = []
        self._changed()

    def _show(self, stroke):
        pts = [p for p, _ in stroke]
        if len(pts) == 1:  # a single spot: a short tick up from it
            pts = [pts[0], (pts[0][0], pts[0][1] + 0.02 / scene_m_per_unit(), pts[0][2])]
        with NoUndo(), PreserveSelection():
            curve = long_name(cmds.curve(degree=1, point=pts, name="scatterDrawing1"))
            shape = cmds.listRelatives(curve, shapes=True, fullPath=True)[0]
            for node in (curve, shape):
                om.MFnDependencyNode(get_dag_path(node).node()).setDoNotWrite(True)  # never saved
            cmds.setAttr(curve + ".hiddenInOutliner", 1)
            cmds.setAttr(shape + ".overrideEnabled", 1)
            cmds.setAttr(shape + ".overrideRGBColors", 1)
            cmds.setAttr(shape + ".overrideColorRGB", 1.0, 0.6, 0.15)
            cmds.setAttr(shape + ".lineWidth", 3.0)
            if cmds.attributeQuery("alwaysDrawOnTop", node=shape, exists=True):
                cmds.setAttr(shape + ".alwaysDrawOnTop", 1)
        return curve

    def _hide(self, curve):
        with NoUndo():
            if curve and cmds.objExists(curve):
                cmds.delete(curve)

    def remove_last(self):
        if self.strokes:
            self.undone.append(self.strokes.pop())
            self._hide(self.curves.pop())
            self._changed()

    def redo_point(self):
        if self.undone:
            stroke = self.undone.pop()
            self.strokes.append(stroke)
            self.curves.append(self._show(stroke))
            self._changed()

    def finish(self):
        self.deactivate()

    def cancel(self):
        self.deactivate()

    def clear(self):
        for c in self.curves:
            self._hide(c)
        self.strokes, self.curves, self.undone = [], [], []
        self._changed()

    def meshes(self):
        return sc_drawing_meshes(self.strokes)


class ScatterStrokeView(object):
    """A layer's stored strokes as lines in the viewport (Show Strokes):
    orange, the picked ones yellow and thicker; outside the undo queue,
    never saved. Clicking a line picks its stroke."""
    RGB = (1.0, 0.6, 0.15)
    PICKED_RGB = (1.0, 0.95, 0.2)

    def __init__(self):
        self.curves = []  # per stroke: its line's transform (None: nothing left of it)
        self.key = None

    def show(self, root, lid, layer, picked=()):
        key = (root, lid, json.dumps((layer or {}).get("draw") or {}, sort_keys=True))
        if key != self.key or not all(c is None or cmds.objExists(c) for c in self.curves):
            self.hide()
            with NoUndo(), PreserveSelection():
                self.curves = [self._make(pts) if pts else None for pts in _sc_drawing_rows(layer)]
            self.key = key
        picked = set(picked or ())
        with NoUndo():
            for i, curve in enumerate(self.curves):
                if curve and cmds.objExists(curve):
                    shape = cmds.listRelatives(curve, shapes=True, fullPath=True)[0]
                    cmds.setAttr(shape + ".overrideColorRGB", *(self.PICKED_RGB if i in picked else self.RGB))
                    cmds.setAttr(shape + ".lineWidth", 5.0 if i in picked else 2.5)

    @staticmethod
    def _make(pts):
        if len(pts) == 1:  # a single spot: a short tick up from it
            pts = [pts[0], (pts[0][0], pts[0][1] + 0.02 / scene_m_per_unit(), pts[0][2])]
        curve = long_name(cmds.curve(degree=1, point=pts, name="scatterStroke1"))
        shape = cmds.listRelatives(curve, shapes=True, fullPath=True)[0]
        for node in (curve, shape):
            om.MFnDependencyNode(get_dag_path(node).node()).setDoNotWrite(True)  # never saved
        cmds.setAttr(curve + ".hiddenInOutliner", 1)
        cmds.setAttr(shape + ".overrideEnabled", 1)
        cmds.setAttr(shape + ".overrideRGBColors", 1)
        if cmds.attributeQuery("alwaysDrawOnTop", node=shape, exists=True):
            cmds.setAttr(shape + ".alwaysDrawOnTop", 1)
        return curve

    def hide(self):
        with NoUndo():
            for curve in self.curves:
                if curve and cmds.objExists(curve):
                    cmds.delete(curve)
        self.curves, self.key = [], None

    def picked_in(self, nodes):
        """Indices of the strokes whose lines are among nodes (None: none are)."""
        found = set()
        for node in nodes or ():
            if not cmds.objExists(node):
                continue
            node = long_name(node)
            if cmds.objectType(node, isAType="shape"):
                node = (cmds.listRelatives(node, parent=True, fullPath=True) or [node])[0]
            if node in self.curves:
                found.add(self.curves.index(node))
        return sorted(found) if found else None


SC_PAINT_CTX = "unlokScatterPaintCtx"
SC_PAINT_SHOW_RGB = {"in": (0.25, 0.95, 0.35), "out": (1.0, 0.28, 0.2), "none": (0.5, 0.5, 0.5)}


class ScatterPainter(SurfacePathDrawer):
    """Paint Influence (the Scatter panel): drag over the group's surfaces to
    paint the layer being edited (Add / Remove / Smooth by Radius and
    Opacity; Ctrl swaps Add and Remove, Shift smooths). Dabs fall every
    quarter radius along the stroke; the stroke is one Ctrl+Z (on_stroke
    stores it), and with Play on the layer grows again when it ends. While
    the tool is on, painted cells show as green (in) / red (out) squares
    and a ring shows the brush: both outside the undo queue, never saved,
    and gone when the tool is."""

    def __init__(self, on_change=None, on_stroke=None, get_brush=None):
        super(ScatterPainter, self).__init__(on_stroke=lambda *a: None, get_smoothing=lambda: 0)
        self.on_change = on_change
        self.on_paint = on_stroke
        self.get_brush = get_brush or (lambda: dict(SC_PAINT_DEFAULTS))
        self.root = self.lid = None
        self.paint = None
        self.nodes, self.boxes, self.spaces = [], {}, {}
        self.surf = None
        self.show = self.ring = None
        self._spots = {}
        self._dabbed = False
        self.last_dab = None
        self.mode = SC_PAINT_MODES[0]
        self._last_show = 0.0
        self.dabs = 0

    # ---------------------------------------------------------- tool
    def activate(self, root, lid):
        if cmds.draggerContext(SC_PAINT_CTX, exists=True):
            cmds.deleteUI(SC_PAINT_CTX)
        cmds.draggerContext(SC_PAINT_CTX, pressCommand=self._press, dragCommand=self._drag,
                            releaseCommand=self._release, finalize=self._finalize, space="screen",
                            cursor="crossHair", undoMode="step")
        cmds.setToolTo(SC_PAINT_CTX)
        self.target(root, lid)
        self._changed()

    @staticmethod
    def is_active():
        try:
            return cmds.currentCtx() == SC_PAINT_CTX
        except RuntimeError:
            return False

    def deactivate(self):
        if self.is_active():
            cmds.setToolTo("selectSuperContext")
        self._delete_display()
        self._changed()

    def shutdown(self):
        try:
            self.deactivate()
        except Exception:
            traceback.print_exc()
        self._delete_display()
        if cmds.draggerContext(SC_PAINT_CTX, exists=True):
            cmds.deleteUI(SC_PAINT_CTX)

    def _finalize(self):  # the user picked another tool
        try:
            self._delete_display()
        except Exception:
            pass
        QtCore.QTimer.singleShot(0, _guarded_call(self._changed))

    def _changed(self):
        if self.on_change is not None:
            self.on_change()

    def target(self, root, lid):
        """Paint this layer of this group (the overlay shows its paint)."""
        self.root, self.lid = root, lid
        self.reload()

    def reload(self):
        """Read the layer's paint and the group's surfaces again (after an
        undo, a Flood, a surface added)."""
        self.paint = sc_paint(self.root, self.lid) if self.root and self.lid else None
        self.nodes, self.boxes, self.spaces = [], {}, {}
        if self.paint is not None:
            for node in sc_surfaces(sc_data(self.root)):
                if _log_shape(node):
                    self.nodes.append(node)
                    self.boxes[node] = _mi_world_box(node)
                    info = _sc_paint_space(node)
                    if info is not None:
                        self.spaces[info[0]] = (node, info[1])
        self.surf = None
        self._spots = {}
        self._update_display(force=True)

    def _surface(self):
        if self.surf is None:
            self.surf = _MiSurface(self.nodes)
        return self.surf

    # ------------------------------------------------------ strokes
    def _press(self):
        try:
            x, y, _ = cmds.draggerContext(SC_PAINT_CTX, q=True, anchorPoint=True)
            self.press_at(x, y, cmds.draggerContext(SC_PAINT_CTX, q=True, modifier=True))
        except Exception:
            traceback.print_exc()

    def _drag(self):
        try:
            x, y, _ = cmds.draggerContext(SC_PAINT_CTX, q=True, dragPoint=True)
            self.drag_at(x, y)
        except Exception:
            traceback.print_exc()

    def _brush(self):
        b = dict(SC_PAINT_DEFAULTS)
        b.update(self.get_brush() or {})
        return b

    def press_at(self, x, y, mod="none"):
        """Start a stroke (only the group's surfaces take paint)."""
        self._reset()
        self.last_dab = None
        self._dabbed = False
        self.anchor = (x, y)
        self.paint = sc_paint(self.root, self.lid) if self.root and self.lid and is_scatter(self.root) else None
        if self.paint is None or not self.nodes:
            self.anchor = None
            return
        self.paint.begin_stroke()
        mode = self._brush()["mode"]
        if mod == "ctrl" and mode != SC_PAINT_MODES[2]:
            mode = SC_PAINT_MODES[1] if mode == SC_PAINT_MODES[0] else SC_PAINT_MODES[0]
        elif mod == "shift":
            mode = SC_PAINT_MODES[2]
        self.mode = mode
        self.candidates = self._make_candidates([get_dag_path(_log_shape(n)) for n in self.nodes])
        self.last_screen = (x, y)
        hit = self._cast(x, y)
        if hit is not None:
            self._dab((hit[0].x, hit[0].y, hit[0].z))
            self._update_display()

    def drag_at(self, x, y):
        if self.anchor is None:
            return
        lx, ly = self.last_screen
        if math.hypot(x - lx, y - ly) < 2.0:
            return
        self.last_screen = (x, y)
        hit = self._cast(x, y)
        if hit is None:
            return
        p = (hit[0].x, hit[0].y, hit[0].z)
        r = self._radius()
        if self.last_dab is None:
            self._dab(p)
        else:
            d = _rl_len(_rl_sub(p, self.last_dab))
            gap = 0.25 * r
            if d < gap:
                return
            n = int(d / gap)
            a = self.last_dab
            for i in range(1, n + 1):
                self._dab(_rl_lerp(a, p, i / float(n)))
        self._update_display()

    def release(self):
        try:
            if self.paint is not None:
                self.paint.end_stroke()
            if self._dabbed and self.on_paint is not None and self.paint is not None:
                self.on_paint(self.paint)
        finally:
            self.anchor = None
            self.last_dab = None
            self._dabbed = False
            self._update_display(force=True)

    def _radius(self):
        return max(1e-4, float(self._brush()["radius"])) / scene_m_per_unit()

    def _dab(self, p):
        r = self._radius()
        near = []
        for node in self.nodes:
            bb = self.boxes.get(node)
            if bb is None or not (bb[0] - r > p[0] or bb[3] + r < p[0] or bb[1] - r > p[1] or bb[4] + r < p[1] or
                                  bb[2] - r > p[2] or bb[5] + r < p[2]):
                near.append(node)
        if near:
            self.paint.dab(p, r, self._brush()["opacity"], self.mode, near)
            self._dabbed = True
            self.dabs += 1
        self.last_dab = p
        self._place_ring(p, r)

    # ------------------------------------------------------ display
    def _quiet_node(self, node):
        for n in [node] + (cmds.listRelatives(node, shapes=True, fullPath=True) or []):
            om.MFnDependencyNode(get_dag_path(n).node()).setDoNotWrite(True)  # never saved
        cmds.setAttr(node + ".hiddenInOutliner", 1)
        cmds.setAttr(node + ".overrideEnabled", 1)
        cmds.setAttr(node + ".overrideDisplayType", 2)  # can't be picked in the viewport

    def _make_display(self):
        """The overlay mesh and the brush ring (made when the tool starts, never mid-stroke)."""
        with NoUndo(), PreserveSelection():
            if self.show is None or not cmds.objExists(self.show):
                self.show = long_name(cmds.polyPlane(width=1, height=1, subdivisionsX=1, subdivisionsY=1,
                                                     constructionHistory=False, name="scatterPaintShow1")[0])
                self._quiet_node(self.show)
                shape = _log_shape(self.show)
                cmds.setAttr(shape + ".displayColors", 1)
                for attr in ("castsShadows", "receiveShadows", "primaryVisibility", "visibleInReflections",
                             "visibleInRefractions"):
                    if cmds.attributeQuery(attr, node=shape, exists=True):
                        cmds.setAttr(shape + "." + attr, False)
                cmds.setAttr(self.show + ".visibility", False)
            if self.ring is None or not cmds.objExists(self.ring):
                self.ring = long_name(cmds.circle(normal=(0, 1, 0), radius=1.0, sections=32, degree=1,
                                                  constructionHistory=False, name="scatterPaintBrush1")[0])
                self._quiet_node(self.ring)
                shape = cmds.listRelatives(self.ring, shapes=True, fullPath=True)[0]
                cmds.setAttr(shape + ".overrideRGBColors", 1)
                cmds.setAttr(shape + ".overrideColorRGB", 1.0, 0.85, 0.2)
                cmds.setAttr(shape + ".overrideEnabled", 1)
                cmds.setAttr(shape + ".lineWidth", 2.0)
                if cmds.attributeQuery("alwaysDrawOnTop", node=shape, exists=True):
                    cmds.setAttr(shape + ".alwaysDrawOnTop", 1)
                cmds.setAttr(self.ring + ".visibility", False)

    def _delete_display(self):
        with NoUndo():
            for node in (self.show, self.ring):
                if node and cmds.objExists(node):
                    cmds.delete(node)
        self.show = self.ring = None

    def _place_ring(self, p, r):
        if not self.ring or not cmds.objExists(self.ring):
            return
        c = self._surface().closest(p)
        n = c[2] if c else (0.0, 1.0, 0.0)
        with NoUndo():
            ft = om.MFnTransform(get_dag_path(self.ring))
            ft.setTranslation(om.MVector(p[0] + n[0] * 0.02 * r, p[1] + n[1] * 0.02 * r, p[2] + n[2] * 0.02 * r),
                              om.MSpace.kTransform)
            ft.setRotation(om.MQuaternion(om.MVector(0.0, 1.0, 0.0), om.MVector(*n)), om.MSpace.kTransform)
            ft.setScale([r, r, r])
            if not cmds.getAttr(self.ring + ".visibility"):
                cmds.setAttr(self.ring + ".visibility", True)

    def shown_cells(self):
        """[(world point, normal, value)] of the painted cells the overlay shows."""
        out = []
        if self.paint is None:
            return out
        h = SC_PAINT_CELL / scene_m_per_unit()
        for uid, (hl, cells) in self.paint.meshes.items():
            space = self.spaces.get(uid)
            if space is None:
                continue
            m16 = space[1]
            for key, v in cells.items():
                if abs(v) < 0.01:
                    continue
                spot = self._spots.get((uid, key))
                if spot is None:
                    w = _sc_paint_xform(m16, ((key[0] + 0.5) * hl, (key[1] + 0.5) * hl, (key[2] + 0.5) * hl))
                    c = self._surface().closest(w)
                    spot = self._spots[(uid, key)] = (c[1], c[2]) if c and c[0] <= 0.55 * h else False
                if spot:
                    out.append((spot[0], spot[1], v))
        return out

    def _update_display(self, force=False):
        """Rebuild the overlay (at most every 0.15 s mid-stroke)."""
        if self.paint is None or not self.is_active():
            self._delete_display()
            return
        now = time.time()
        if not force and now - self._last_show < 0.15:
            return
        self._last_show = now
        if self.show is None or not cmds.objExists(self.show) or self.ring is None or not cmds.objExists(self.ring):
            if self.anchor is not None:
                return  # never make nodes mid-stroke
            self._make_display()
        h = SC_PAINT_CELL / scene_m_per_unit()
        half, lift = 0.47 * h, 0.04 * h
        pts, counts, conn, cols = [], [], [], []
        grey = SC_PAINT_SHOW_RGB["none"]
        for p, n, v in self.shown_cells():
            t1, t2 = _mi_frame(n)
            o = _rl_add(p, _rl_mul(n, lift))
            k = len(pts)
            for a, b in ((-1, -1), (1, -1), (1, 1), (-1, 1)):
                pts.append(om.MPoint(o[0] + (t1[0] * a + t2[0] * b) * half, o[1] + (t1[1] * a + t2[1] * b) * half,
                                     o[2] + (t1[2] * a + t2[2] * b) * half))
            counts.append(4)
            conn.extend((k, k + 1, k + 2, k + 3))
            rgb = SC_PAINT_SHOW_RGB["in" if v > 0.0 else "out"]
            a = min(1.0, abs(v))
            cols.append(om.MColor((grey[0] + (rgb[0] - grey[0]) * a, grey[1] + (rgb[1] - grey[1]) * a,
                                   grey[2] + (rgb[2] - grey[2]) * a)))
        with NoUndo():
            if not counts:
                if cmds.getAttr(self.show + ".visibility"):
                    cmds.setAttr(self.show + ".visibility", False)
                return
            shape = _log_shape(self.show)
            fn = om.MFnMesh(get_dag_path(shape))
            fn.createInPlace(om.MPointArray(pts), counts, conn)
            fn = om.MFnMesh(get_dag_path(shape))  # a fresh function set after the topology change
            fn.setFaceColors(om.MColorArray(cols), list(range(len(counts))))
            if not cmds.getAttr(self.show + ".visibility"):
                cmds.setAttr(self.show + ".visibility", True)


class _ScLayerNameDelegate(QtWidgets.QStyledItemDelegate):
    """Renaming a layer edits just its name, not the notes after it
    ("(drawn, 2 strokes)", "(changed)")."""

    def setEditorData(self, editor, index):
        name = index.data(QtCore.Qt.UserRole + 2)
        if name and isinstance(editor, QtWidgets.QLineEdit):
            editor.setText(name)
            editor.selectAll()
        else:
            super(_ScLayerNameDelegate, self).setEditorData(editor, index)


class ScatterPanel(QtWidgets.QWidget):
    TOOL_NAME = "Scatter"
    TOOL_TIP = "Scatter groups: moss, dry grass, dead leaves, leaf piles, moss tufts and ivy on your meshes, in " \
               "layers you control one by one."

    def __init__(self, parent=None):
        super(ScatterPanel, self).__init__(parent)
        self._jobs = []
        self._pending = set()
        self._root = None   # the group being edited (stays while you select meshes to add)
        self._root_uid = None  # its uuid: followed when it's moved (into a publish group, say)
        self._lid = None    # the layer being edited
        self._filling = False
        self._sel_now = None  # the selection read by _sync_from_selection, while it refreshes
        self._sel_timer = QtCore.QTimer(self)
        self._sel_timer.setSingleShot(True)
        self._sel_timer.setInterval(80)
        self._sel_timer.timeout.connect(_guarded(self._sel_timer, self._sync_from_selection))
        self._edit_timer = QtCore.QTimer(self)
        self._edit_timer.setSingleShot(True)
        self._edit_timer.setInterval(60)
        self._edit_timer.timeout.connect(_guarded(self._edit_timer, self._apply_pending))
        self._slow = False  # the last update took a while: a slider drag updates once, on release
        # each layer's last update time: a drag on a layer known to be slow drafts from its first tick (it
        # used to grow one full update first, a freeze of seconds on a big moss layer, before drafting)
        self._took = {}
        # per type: what the next group's first layer gets (the settings shown with no layer picked), kept
        # apart from the layers shown since, so a new group never picks up the last layer looked at
        self._next = {}
        self._drag_draft = False  # moss grown as a draft while a slider was held: in full once it's let go
        self._undo_timer = QtCore.QTimer(self)
        self._undo_timer.setSingleShot(True)
        self._undo_timer.setInterval(50)
        self._undo_timer.timeout.connect(_guarded(self._undo_timer, self._after_undo))
        self.drawer = ScatterDrawer(on_change=lambda: self._drawing_changed())
        self.stroke_view = ScatterStrokeView()
        self.painter = ScatterPainter(on_change=lambda: self._drawing_changed(),
                                      on_stroke=lambda paint: self._paint_stroke(paint), get_brush=lambda: self._brush())
        self.draw_sec = {}
        self.clump_sec = {}
        self.mat_sec = {}
        self.fade_sec = {}
        self.row_lbl = {}
        self._build()
        self._install_jobs()

    def showEvent(self, event):
        super(ScatterPanel, self).showEvent(event)
        try:  # groups from before: boxes out beside them, nothing locked
            for root in sc_groups():
                sc_fix_box(root)
        except Exception:
            traceback.print_exc()
        self._sel_timer.start()

